/**
 * Merge a head branch into a base branch using GitHub's merge API.
 * This creates a merge commit directly without requiring a pull request.
 */
export async function mergeBranch(
  repoFullName: string,
  head: string,
  base: string,
  commitMessage: string,
  accessToken: string,
): Promise<{ sha: string }> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  }

  const response = await fetch(`${GITHUB_API}/repos/${repoFullName}/merges`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      base,
      head,
      commit_message: commitMessage,
    }),
  })

  if (response.status === 409) {
    throw new Error("Merge conflict: the branches cannot be merged automatically")
  }

  if (response.status === 204) {
    // 204 means base already contains the head (nothing to merge)
    return { sha: "" }
  }

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Failed to merge ${head} into ${base}: ${response.status} - ${text}`)
  }

  const data = await response.json<{ sha: string }>()
  return { sha: data.sha }
}

/** Thrown when GitHub rejects a PR merge (not mergeable / conflict). */
export class PullRequestNotMergeableError extends Error {
  status: number
  constructor(message: string, status: number) {
    super(message)
    this.name = "PullRequestNotMergeableError"
    this.status = status
  }
}

/**
 * Mark a draft PR ready via GraphQL (REST can't update `draft`). Pass
 * `knownNodeId` to skip the state fetch — the caller must have confirmed the PR
 * is a draft, since this path runs the mutation unconditionally. Without it,
 * fetches state and no-ops if the PR is already ready.
 */
export async function markPullRequestReady(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
  knownNodeId?: string,
): Promise<void> {
  let nodeId = knownNodeId
  if (!nodeId) {
    const state = await getPullRequestState(repoFullName, prNumber, accessToken)
    if (!state) {
      throw new Error(`Pull request #${prNumber} not found in ${repoFullName}`)
    }
    if (!state.draft) return
    nodeId = state.node_id
  }

  await githubGraphQL(
    accessToken,
    `mutation($id: ID!) {
      markPullRequestReadyForReview(input: { pullRequestId: $id }) {
        pullRequest { id isDraft }
      }
    }`,
    { id: nodeId },
  )
}

/**
 * Fetch the repo's allowed merge methods (the PR merge endpoint is gated by
 * them, unlike /merges). Defaults all to true if the repo can't be read.
 */
export async function getAllowedMergeMethods(
  repoFullName: string,
  accessToken: string,
): Promise<{ merge: boolean; squash: boolean; rebase: boolean }> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}`, {
    headers: githubHeaders(accessToken),
  })
  if (!response.ok) {
    response.body?.cancel()
    return { merge: true, squash: true, rebase: true }
  }
  const data = await response.json<{
    allow_merge_commit?: boolean
    allow_squash_merge?: boolean
    allow_rebase_merge?: boolean
  }>()
  return {
    merge: data.allow_merge_commit ?? true,
    squash: data.allow_squash_merge ?? true,
    rebase: data.allow_rebase_merge ?? true,
  }
}

/**
 * Pick an allowed merge method, preferring merge, then squash, then rebase.
 * GitHub never lets a repo disable all three, so the final fallback is
 * unreachable in practice; if it ever fires, the merge gets a 405 that the
 * caller maps to a clear "could not be merged" error rather than guessing.
 */
export function pickMergeMethod(allowed: {
  merge: boolean
  squash: boolean
  rebase: boolean
}): "merge" | "squash" | "rebase" {
  if (allowed.merge) return "merge"
  if (allowed.squash) return "squash"
  if (allowed.rebase) return "rebase"
  return "merge"
}

/**
 * Merge a pull request via PUT /repos/{owner}/{repo}/pulls/{number}/merge.
 * Mirrors mergeBranch()'s return shape. Throws PullRequestNotMergeableError on
 * 405 (not mergeable) / 409 (head changed) so callers can surface a 422.
 */
export async function mergePullRequest(
  repoFullName: string,
  prNumber: number,
  commitTitle: string,
  accessToken: string,
  method: "merge" | "squash" | "rebase" = "merge",
): Promise<{ sha: string }> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}/merge`,
    {
      method: "PUT",
      headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
      body: JSON.stringify({ commit_title: commitTitle, merge_method: method }),
    },
  )

  if (response.status === 405 || response.status === 409) {
    const text = await response.text()
    throw new PullRequestNotMergeableError(
      `Pull request #${prNumber} is not mergeable: ${response.status} - ${text}`,
      response.status,
    )
  }

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Failed to merge pull request #${prNumber}: ${response.status} - ${text}`)
  }

  const data = await response.json<{ sha: string; merged: boolean }>()
  return { sha: data.sha }
}

