// GitHub PR management for trail CI triggering.
// When a user explicitly requests CI for a trail, we find or create a PR so that
// pull_request-triggered GitHub Actions workflows run. If a user-created PR already
// exists for the branch, we track it. Otherwise we create a shadow draft PR. Shadow
// draft PRs are automatically closed when the trail is merged, closed, or deleted;
// user-created PRs are left alone.

import type { Db } from "./db/db-types"
import type { TrailRow } from "./db/db-types"
import {
  createPullRequest,
  closePullRequest,
  getPullRequestState,
  findOpenPullRequest,
} from "./github"
import { buildTrailLinkBlock, buildTrailUrl } from "./trail-pr-shared"

// HTML-comment marker we embed in the body of every shadow PR we create.
// Used at close-time to distinguish our PRs from user-authored ones (the
// title is now a plain copy of the trail title and is no longer a
// reliable signal). The marker is invisible in rendered Markdown.
const SHADOW_PR_MARKER = "<!-- entire-shadow-pr -->"
/** Statuses for which we skip PR tracking */
const INACTIVE_STATUSES = new Set(["merged", "closed"])

function buildShadowPRBody(trailUrl: string): string {
  return [
    buildTrailLinkBlock(trailUrl),
    "",
    "This draft pull request was opened by [Entire](https://entire.io) after CI was requested for the linked trail. Feel free to edit the title or body — the link above is what keeps the trail and PR connected.",
    "",
    SHADOW_PR_MARKER,
  ].join("\n")
}

/**
 * Ensure a PR is tracked for the given trail. If an open PR already exists for
 * the branch (user-created or previous shadow), track it. Otherwise create a
 * shadow draft PR. Returns the PR number or null if skipped.
 */
export async function ensureTrailPR(
  db: Db,
  repoFullName: string,
  repoId: string,
  trail: TrailRow,
  accessToken: string,
  frontendBaseUrl: string,
): Promise<number | null> {
  if (!trail.branch || INACTIVE_STATUSES.has(trail.status)) {
    return null
  }

  // If we already have a tracked PR, verify it still exists and is open
  if (trail.gh_pr_id) {
    const existing = await getPullRequestState(repoFullName, trail.gh_pr_id, accessToken)
    if (existing && existing.state === "open") {
      return trail.gh_pr_id
    }
    // PR was closed or deleted externally — clear and look for / create a new one
    await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: null })
  }

  // Check if an open PR already exists for this branch → base (user-created)
  const existingPR = await findOpenPullRequest(repoFullName, trail.branch, trail.base, accessToken)
  if (existingPR) {
    await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: existingPR.number })
    return existingPR.number
  }

  // No existing PR — create a shadow draft PR
  const trailUrl = buildTrailUrl(frontendBaseUrl, repoFullName, trail.number)
  const prNumber = await createPullRequest(
    repoFullName,
    trail.branch,
    trail.base,
    trail.title,
    buildShadowPRBody(trailUrl),
    accessToken,
    { draft: true, reopenClosed: false },
  )

  await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: prNumber })
  return prNumber
}

/**
 * Look for an existing open PR targeting the trail's base branch and link it as
 * gh_pr_id when one is found. Does NOT create a shadow PR — purely a passive
 * lookup for when a trail is created or loaded.
 *
 * Returns the linked PR metadata, or null if nothing was linked.
 */
export async function linkExistingPR(
  db: Db,
  repoFullName: string,
  repoId: string,
  trail: TrailRow,
  fallbackBase: string,
  accessToken: string,
): Promise<{ number: number } | null> {
  if (trail.gh_pr_id || !trail.branch || INACTIVE_STATUSES.has(trail.status)) {
    return null
  }
  const base = trail.base || fallbackBase
  const existingPR = await findOpenPullRequest(repoFullName, trail.branch, base, accessToken)
  if (!existingPR) return null
  await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: existingPR.number })
  trail.gh_pr_id = existingPR.number
  return { number: existingPR.number }
}

/**
 * Close the tracked PR for a trail if it's a shadow draft PR (not user-created).
 * Clears the tracking field regardless.
 */
export async function closeTrailPR(
  db: Db,
  repoFullName: string,
  repoId: string,
  trail: TrailRow,
  accessToken: string,
): Promise<void> {
  if (!trail.gh_pr_id) return

  const prState = await getPullRequestState(repoFullName, trail.gh_pr_id, accessToken)
  if (prState?.state === "closed") {
    await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: null })
    return
  }

  // Only close PRs we created. The marker is the reliable ownership signal —
  // it's embedded when we open the shadow PR; PRs we merely linked won't have
  // it. Draft state is NOT a signal: we may have published the shadow PR at
  // merge time (markPullRequestReady), so gate on the marker alone or a
  // published-then-abandoned shadow PR would leak.
  if (prState && prState.body.includes(SHADOW_PR_MARKER)) {
    await closePullRequest(repoFullName, trail.gh_pr_id, accessToken)
  }

  await db.trails.updateMetadata(repoId, trail.id, { gh_pr_id: null })
}

