function countFailingChecks(checks: TrailMergeability["checks"] | TrailChecksStatus["checks"]) {
  return checks.filter(
    (check) =>
      check.status === "completed" &&
      (check.conclusion === "failure" ||
        check.conclusion === "timed_out" ||
        check.conclusion === "cancelled"),
  ).length
}

function markChecksPendingAfterBranchUpdate<T extends TrailMergeability["checks"]>(checks: T): T {
  return checks.map((check) => ({
    ...check,
    status: check.status === "completed" ? "queued" : check.status,
    conclusion: null,
    started_at: null,
    completed_at: null,
  })) as T
}

function markTrailChecksPendingAfterBranchUpdate(
  previous: TrailChecksStatus | undefined,
  headSha: string,
): TrailChecksStatus {
  return {
    state: "pending",
    head_sha: headSha,
    total_count: previous?.total_count ?? 0,
    checks: previous ? markChecksPendingAfterBranchUpdate(previous.checks) : [],
    ci_pr: previous?.ci_pr,
    automation: previous?.automation ?? null,
  }
}

function markMergeabilityPendingAfterBranchUpdate(
  previous: TrailMergeability | undefined,
): TrailMergeability | undefined {
  if (!previous) return previous

  return {
    ...previous,
    checks_passed: false,
    checks_status: "pending",
    checks: markChecksPendingAfterBranchUpdate(previous.checks),
    behind_by: 0,
    mergeable: false,
  }
}

