// PR actions that affect the open PR list
const PR_RELEVANT_ACTIONS = new Set([
  "opened",
  "edited",
  "closed",
  "reopened",
  "converted_to_draft",
  "ready_for_review",
])

async function tryGetWebhookInstallationToken(args: {
  env: Env
  installationId: number
  logContext: string
}): Promise<string | null> {
  try {
    return await getInstallationToken(
      args.installationId,
      { appId: args.env.GITHUB_CLIENT_ID, privateKey: args.env.GITHUB_APP_PRIVATE_KEY },
      args.env.ENTIRE_CACHE,
    )
  } catch (err) {
    console.error(`[trail-assignees] webhook token failed ${args.logContext}`, err)
    return null
  }
}

// Extract PR data from webhook payload
function extractPRData(payload: Record<string, unknown>): WebhookPRData | null {
  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr || typeof pr.id !== "number") {
    return null
  }

  const head = pr.head as Record<string, unknown> | undefined
  const user = pr.user as Record<string, unknown> | undefined

  return {
    github_pr_id: pr.id as number,
    number: pr.number as number,
    title: pr.title as string,
    html_url: pr.html_url as string,
    state: pr.merged_at ? "merged" : (pr.state as string),
    draft: (pr.draft as boolean) ?? false,
    created_at: pr.created_at as string,
    updated_at: pr.updated_at as string,
    merged_at: (pr.merged_at as string | null) || null,
    body: ((pr.body as string | null) || null)?.slice(0, 60000) ?? null,
    head_branch: (head?.ref as string | null) || null,
    user_login: (user?.login as string | null) || null,
  }
}

// Process pull_request webhook event - update PR in database
export async function processPullRequestEvent(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  env?: Env,
): Promise<void> {
  if (eventType !== "pull_request") {
    return
  }

  if (!action || !PR_RELEVANT_ACTIONS.has(action)) {
    console.log(`PR event ${action}: not relevant for DB, skipping`)
    return
  }

  // Validate installation exists before processing
  // This prevents unauthorized data modification from compromised webhook secrets
  const installationId = await validateInstallation(payload, db, `PR event ${action}`)
  if (installationId === null) {
    console.log(`PR event ${action}: no installation ID in payload, skipping`)
    return
  }

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo || typeof repo.full_name !== "string" || typeof repo.id !== "number") {
    console.log(`PR event: no repository data, skipping`)
    return
  }

  const repoGithubId = repo.id as number
  const repoFullName = repo.full_name as string
  const prData = extractPRData(payload)
  if (!prData) {
    console.log(`PR event: no pull_request data, skipping`)
    return
  }

  let dbChanges = 0

  if (action === "opened" || action === "reopened" || action === "edited") {
    // Insert or update PR in the global repo_pull_requests table
    dbChanges = await db.prs.upsertPRFromWebhook(repoGithubId, prData)
    console.log(`PR ${action} #${prData.number} for ${repoFullName}: upserted ${dbChanges} row(s)`)
  } else if (action === "closed") {
    // Upsert PR with closed/merged state (preserves merged_at for metrics)
    dbChanges = await db.prs.upsertPRFromWebhook(repoGithubId, prData)
    console.log(
      `PR closed #${prData.number} for ${repoFullName}: upserted ${dbChanges} row(s), merged_at=${prData.merged_at}`,
    )
  } else if (action === "converted_to_draft" || action === "ready_for_review") {
    // Update draft status
    const draft = action === "converted_to_draft"
    dbChanges = await db.prs.updatePRDraftStatusByGithubIds(
      repoGithubId,
      prData.github_pr_id,
      draft,
    )
    console.log(
      `PR ${action} #${prData.number} for ${repoFullName}: updated draft status ${dbChanges} row(s)`,
    )
  }

  // Note: sync:lastUpdate cache invalidation is already handled by processWebhookEvent
  // for all pull_request events, so we don't duplicate it here (Cloudflare KV has a
  // 1 write/sec/key rate limit that would cause 429 errors).

  // Index PR to Turbopuffer for search
  if (env?.TURBOPUFFER_API_KEY && env?.COHERE_API_KEY && dbChanges > 0) {
    const orgName = repoFullName.split("/")[0]
    try {
      await indexPRDocuments(env.TURBOPUFFER_API_KEY, env.COHERE_API_KEY, orgName, repoGithubId, [
        {
          github_pr_id: prData.github_pr_id,
          number: prData.number,
          title: prData.title,
          body: prData.body,
          head_branch: prData.head_branch,
          user_login: prData.user_login,
          state: prData.state,
          created_at: prData.created_at,
          merged_at: prData.merged_at,
          html_url: prData.html_url,
          repo_github_id: repoGithubId,
        },
      ])
    } catch (err) {
      console.error(`[webhook] pr_index_error`, err instanceof Error ? err.message : String(err))
    }
  }
}

// Mark a trail as merged when its associated PR is merged.
// Complements the push-based merge detection — this path is faster since the
// webhook payload already confirms the merge (no GitHub compare API needed).
export async function processTrailMergeOnPRClose(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  env?: Env,
): Promise<void> {
  if (eventType !== "pull_request" || action !== "closed") return

  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr?.merged_at) return

  const installationId = await validateInstallation(payload, db, "Trail merge on PR close")
  if (installationId === null) return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo || typeof repo.id !== "number") return

  const repoGithubId = repo.id as number
  const repoFullName = (repo.full_name as string) ?? "unknown"

  try {
    const repoRecord = await db.repos.getByGithubId(repoGithubId)
    if (!repoRecord) return

    const head = pr.head as Record<string, unknown> | undefined
    const base = pr.base as Record<string, unknown> | undefined
    const headBranch = head?.ref as string | undefined
    const headSha = head?.sha as string | undefined
    const baseSha = base?.sha as string | undefined
    const mergedAt = pr.merged_at as string

    if (!headBranch) return

    // Use the original-branch fallback: if GitHub's branch-delete push event landed
    // before this pull_request:closed event, the branch claim is already released
    // (branch is null) and a plain getByBranch lookup would miss the trail.
    const trail = await db.trails.getByBranchOrOriginalBranch(repoRecord.id, headBranch)
    if (!trail) return
    if (trail.status === "merged" || trail.status === "closed") return

    // Compute merge_base_sha via GitHub compare API so file diffs survive branch deletion.
    // Use base.sha (pre-merge tip of base branch) instead of the branch name — by the time
    // this handler runs, the branch ref already points to the post-merge commit.
    let mergeBaseSha: string | null = null
    if (env && headSha && baseSha) {
      try {
        const token = await getInstallationToken(
          installationId,
          { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
          env.ENTIRE_CACHE,
        )
        mergeBaseSha = await getMergeBaseSha(repoFullName, baseSha, headSha, token)
      } catch (err) {
        console.log(
          `[trails-merge-pr] merge_base_sha lookup failed for ${repoFullName}: ${err instanceof Error ? err.message : String(err)}`,
        )
      }
    }

    await db.trails.updateMetadata(repoRecord.id, trail.id, {
      status: "merged",
      merged_at: mergedAt,
      updated_at: new Date().toISOString(),
      ...(headSha && { head_sha: headSha }),
      ...(mergeBaseSha && { merge_base_sha: mergeBaseSha }),
    })

    console.log(
      `[trails-merge-pr] merged trail=#${trail.number} repo=${repoFullName} branch=${headBranch}`,
    )

    // Close shadow draft PR if one exists (leaves user-created PRs alone)
    if (trail.gh_pr_id && env) {
      try {
        const token = await getInstallationToken(
          installationId,
          { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
          env.ENTIRE_CACHE,
        )
        await closeTrailPR(db, repoFullName, repoRecord.id, trail, token)
      } catch {
        // Non-critical
      }
    }
  } catch (err) {
    console.error(
      `[trails-merge-pr] failed repo=${repoFullName}: ${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

// When a PR is opened, populate gh_pr_id on the matching trail row (if a
// trail exists for the head branch and isn't already linked). Same-repo PRs
// only: a fork PR's head.ref could collide with a trail branch name on the
// base repo, which would otherwise wrongly link them.
export async function processTrailGhPrIdLinkOnPROpened(
  eventType: string,
  action: string | null,
