function toTitleCaseToken(token: string): string {
  if (!token) return token
  return token[0].toUpperCase() + token.slice(1)
}

export function buildAutoTrailTitle(branch: string): string {
  const normalized = branch
    .replace(/^refs\/heads\//, "")
    .replace(/[-_/]+/g, " ")
    .replace(/\s+/g, " ")
    .trim()

  if (!normalized) return "New Trail"
  return normalized.split(" ").map(toTitleCaseToken).join(" ")
}

export function canAutoCreateTrailForBranch(
  branch: string,
  defaultBranch: string,
  baseBranch: string = defaultBranch,
): boolean {
  if (!branch) return false
  if (branch === baseBranch) return false
  if (branch === defaultBranch) return false
  if (branch === CHECKPOINT_BRANCH) return false
  if (branch.startsWith("entire/")) return false
  if (branch.startsWith("gh-readonly-queue/")) return false
  return true
}

/**
 * Ensure a trail row exists for the given branch. If concurrent webhooks
 * race on the same branch (e.g. push + create + pull_request/opened all
 * arriving simultaneously), they converge on the same per-repo sequential
 * `number` — the allocator lives inside a transaction that resolves branch
 * conflicts authoritatively, so no caller ever returns a number that
 * isn't persisted. An unknown `authorLogin` produces a null author.
 */
export async function ensureAutoTrailForBranch(
  db: Db,
  repo: Repo,
  branch: string,
  authorLogin: string,
  options: { title?: string | null; assignees?: string[]; base?: string | null } = {},
): Promise<{ created: boolean; number: number | null }> {
  const defaultBranch = repo.default_branch ?? "main"
  const base = options.base?.trim() || defaultBranch
  if (!repo.trails_enabled || !canAutoCreateTrailForBranch(branch, defaultBranch, base)) {
    return { created: false, number: null }
  }

  const existing = await db.trails.getByBranch(repo.id, branch)
  if (existing) {
    return { created: false, number: existing.number }
  }

  const authorUserId = authorLogin ? await db.users.findIdByLogin(authorLogin) : null
  const now = new Date().toISOString()

  const explicitTitle = options.title?.trim()
  const title = explicitTitle ? explicitTitle : buildAutoTrailTitle(branch)

  const result = await db.trails.create({
    repo_id: repo.id,
    branch,
    base,
    title,
    status: "open",
    author_user_id: authorUserId,
    assignees: options.assignees ?? [],
    type: "task",
    priority: "none",
    created_at: now,
    updated_at: now,
  })

  return { created: result.created, number: result.row.number }
}

