// When a PR is opened, populate gh_pr_id on the matching trail row (if a
// trail exists for the head branch and isn't already linked). Same-repo PRs
// only: a fork PR's head.ref could collide with a trail branch name on the
// base repo, which would otherwise wrongly link them.
export async function processTrailGhPrIdLinkOnPROpened(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
): Promise<void> {
  if (eventType !== "pull_request") return
  if (action !== "opened" && action !== "ready_for_review") return

  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr) return
  if (action === "opened" && pr.draft === true) return

  const installationId = await validateInstallation(payload, db, "Trail gh_pr_id link on PR open")
  if (installationId === null) return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo || typeof repo.id !== "number") return

  const repoGithubId = repo.id as number
  const prNumber = pr.number as number | undefined
  const head = pr.head as Record<string, unknown> | undefined
  const base = pr.base as Record<string, unknown> | undefined
  const headBranch = head?.ref as string | undefined
  const headRepo = head?.repo as { id?: unknown } | undefined
  const baseRepo = base?.repo as { id?: unknown } | undefined

  if (!prNumber || !headBranch) return
  if (typeof headRepo?.id !== "number" || headRepo.id !== baseRepo?.id) return

  try {
    const repoRecord = await db.repos.getByGithubId(repoGithubId)
    if (!repoRecord) return

    const dbInstallationId = await db.installations.findIdByGitHubId(installationId)
    if (!dbInstallationId || repoRecord.installation_id !== dbInstallationId) return

    const trail = await db.trails.getByBranch(repoRecord.id, headBranch)
    if (!trail || trail.gh_pr_id) return

    await db.trails.updateMetadata(repoRecord.id, trail.id, { gh_pr_id: prNumber })
  } catch (err) {
    console.error(
      `[trails-pr-id-link] failed repo=${repo.full_name as string} pr=#${prNumber}: ${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

// When a PR is opened non-draft or marked ready for review, ensure a trail
// exists for the head branch, derive assignees from branch contributors, and
// prepend a Trail link to the PR body on entire.io.
export async function processTrailLinkOnPROpened(
  eventType: string,
  action: string | null,
  payload: Record<string, unknown>,
  db: Db,
  env: Env,
): Promise<void> {
  if (eventType !== "pull_request") return
  if (action !== "opened" && action !== "ready_for_review") return

  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr) return
  if (action === "opened" && pr.draft === true) return

  const installationId = await validateInstallation(payload, db, "Trail link on PR open")
  if (installationId === null) return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo || typeof repo.id !== "number" || typeof repo.full_name !== "string") return

  const repoGithubId = repo.id as number
  const repoFullName = repo.full_name as string
  const prNumber = pr.number as number | undefined
  const head = pr.head as Record<string, unknown> | undefined
  const base = pr.base as Record<string, unknown> | undefined
  const headBranch = head?.ref as string | undefined
  const prBaseBranch = typeof base?.ref === "string" ? base.ref.trim() || undefined : undefined
  const headRepo = head?.repo as { id?: unknown } | undefined
  const baseRepo = base?.repo as { id?: unknown } | undefined
  const user = pr.user as { login?: unknown } | undefined
  const author = typeof user?.login === "string" ? user.login : "unknown"
  const existingBody = typeof pr.body === "string" ? pr.body : ""
  const prTitle = typeof pr.title === "string" ? pr.title : null

  if (!prNumber || !headBranch) return
  if (headRepo?.id !== baseRepo?.id) return

  try {
    const repoRecord = await db.repos.getByGithubId(repoGithubId)
    if (!repoRecord) return

    const dbInstallationId = await db.installations.findIdByGitHubId(installationId)
    if (!dbInstallationId || repoRecord.installation_id !== dbInstallationId) return

    const compareBase = prBaseBranch ?? repoRecord.default_branch ?? "main"
    let token = await tryGetWebhookInstallationToken({
      env,
      installationId,
      logContext: `pr-open repo=${repoFullName} pr=${prNumber}`,
    })
    const assignees = token
      ? await tryGetBranchContributorAssignees({
          db,
          env,
          repoFullName,
          base: compareBase,
          branch: headBranch,
          accessToken: token,
          logContext: `pr-open repo=${repoFullName} pr=${prNumber}`,
        })
      : []

    const { number } = await ensureAutoTrailForBranch(db, repoRecord, headBranch, author, {
      title: prTitle,
      assignees,
      base: compareBase,
    })
    if (number === null) return

    const trail = await db.trails.getByBranch(repoRecord.id, headBranch)
    if (trail) {
      await db.trails.mergeAssignees(repoRecord.id, trail.id, assignees)
    }

    let frontendHost: string | null = null
    try {
      frontendHost = new URL(env.FRONTEND_BASE_URL).hostname
    } catch {
      return
    }
    if (frontendHost !== "entire.io") return

    const link = buildTrailUrl(env.FRONTEND_BASE_URL, repoFullName, number)
    const block = buildTrailLinkBlock(link)
    if (bodyHasTrailLink(existingBody, link)) return

    token ??= await getInstallationToken(
      installationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE,
    )

    const latestBody = await fetchPullRequestBody(repoFullName, prNumber, token)
    if (bodyHasTrailLink(latestBody, link)) return

    const newBody = prependTrailLinkBlock(latestBody, block)
    await updatePullRequestBody(repoFullName, prNumber, newBody, token)

    console.log(`[trails-pr-link] injected trail=#${number} repo=${repoFullName} pr=#${prNumber}`)
  } catch (err) {
    console.error(
      `[trails-pr-open] failed repo=${repoFullName} pr=#${prNumber}: ${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

