/**
 * Ensure a backing PR exists (via ensureTrailPR) for an open trail when its
 * branch is pushed, so CI runs and protected-base merges work. Does not create
 * trails. Failures are swallowed — must never break the push pipeline.
 */
export async function processTrailEnsurePROnPush(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env,
): Promise<void> {
  if (eventType !== "push") return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo?.full_name) return

  const ref = payload.ref as string | undefined
  if (!ref?.startsWith("refs/heads/")) return
  const branch = ref.replace("refs/heads/", "")

  if (branch === CHECKPOINT_BRANCH) return

  // Nothing to open a PR for on deletions or force-pushes.
  if (payload.deleted === true || payload.forced === true) return

  const repoFullName = repo.full_name as string
  const repoGithubId = repo.id as number

  const repoRecord = await db.repos.getByGithubId(repoGithubId)
  if (!repoRecord || !repoRecord.trails_enabled) return

  const trail = await db.trails.getByBranch(repoRecord.id, branch)
  if (!trail || trail.status !== "open" || !trail.branch) return

  const installationId = await validateInstallation(payload, db, `Trail ensure PR ${repoFullName}`)
  if (installationId === null) return

  let token: string
  try {
    token = await getInstallationToken(
      installationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE,
    )
  } catch {
    return
  }

  try {
    // Skip empty PRs; only skip when we positively know the branch isn't ahead.
    const comparison = await compareBranchStatus(repoFullName, trail.base, trail.branch, token)
    if (comparison && comparison.ahead_by === 0) return

    // Idempotent — relies on GitHub dedup for concurrent creates.
    const prNumber = await ensureTrailPR(
      db,
      repoFullName,
      repoRecord.id,
      trail,
      token,
      env.FRONTEND_BASE_URL,
    )
    if (prNumber) {
      console.log(
        `[trails-ensure-pr] trail=#${trail.number} repo=${repoFullName} branch=${trail.branch} pr=#${prNumber}`,
      )
    }
  } catch (err) {
    console.log(
      `[trails-ensure-pr] error repo=${repoFullName} branch=${branch} error=${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

