    const { db, userId, repo: repoAccess, repoFullName, trail: row } = ctx
    const noChecks = { state: "none", total_count: 0, checks: [] } satisfies BranchCheckStatus
    const isTerminalTrail = row.status === "merged" || row.status === "closed"
    const terminalHeadSha = isTerminalTrail ? row.head_sha : null

    type CachedChecks = {
      fetched_at: number
      payload: BranchCheckStatus & { head_sha?: string }
    }
    const cacheKey = terminalHeadSha
      ? `trail-checks:${repoFullName}:${row.number}:${terminalHeadSha}`
      : `trail-checks:${repoFullName}:${row.number}`
    const CACHE_FRESHNESS_MS = 5_000

    const buildAutomation = async (): Promise<FixCiAutomationState | null> => {
      const latest = await db.sandboxRuns.getLatestForTrail({
        automation: "fix_ci",
        trail_id: row.id,
      })
      if (!latest) return null

      const isActive = isFixCiRunActive(latest.status, latest.prompt_status)
      if (isActive) {
        return {
          state: "running",
          run_id: latest.id,
          started_at: latest.created_at,
          started_at_sha: latest.head_sha,
        }
      }

      let outcome: FixCiAutomationState["outcome"]
      if (latest.status === "succeeded") outcome = "succeeded"
      else if (latest.status === "failed" || latest.status === "timeout") outcome = "failed"
      else if (latest.status === "canceled") outcome = "canceled"
      else return null

      const doneEvent = await db.sandboxRuns.getLatestEventByType(latest.id, "done")
      const payload = doneEvent?.payload as { pushedHeadSha?: string | null } | null

      return {
        state: "completed",
        outcome,
        run_id: latest.id,
        started_at: latest.created_at,
        started_at_sha: latest.head_sha,
        pushed_head_sha: payload?.pushedHeadSha ?? null,
      }
    }

    const cached = await c.env.ENTIRE_CACHE.get<CachedChecks>(cacheKey, "json")
    if (cached && Date.now() - cached.fetched_at < CACHE_FRESHNESS_MS) {
      const automation = !isTerminalTrail && row.branch ? await buildAutomation() : null
      return c.json({ ...cached.payload, automation })
    }

    const writeCache = (payload: CachedChecks["payload"]) =>
      runInBackground(c, () =>
        c.env.ENTIRE_CACHE.put(
