          {
            error: publishedDraft
              ? "Required checks are now running — try merging again once they pass"
              : "This trail could not be merged",
          },
          422,
        )
      }
      console.error(`Failed to merge trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to merge trail" }, 500)
    }
  },
)

