/**
 * Check if any trail's feature branch has been merged into the pushed base branch.
 * Reads trail data from the DB and uses the GitHub compare API for merge detection.
 */
async function checkAndMergeTrails(
  env: Env,
  db: Db,
  repoId: string,
  repoFullName: string,
  pushedBranch: string,
  beforeSha: string,
  token: string,
): Promise<void> {
  // Get all trails from DB whose base matches the pushed branch
  const { trails: allTrails } = await db.trails.listByRepo(repoId)
  const isNewBranch = beforeSha === "0000000000000000000000000000000000000000"

  for (const trail of allTrails) {
    if (!trail.branch) continue
    if (trail.base !== pushedBranch) continue
    if (trail.status === "merged" || trail.status === "closed") continue

    try {
      let merged = await isBranchMergedInto(repoFullName, pushedBranch, trail.branch, token)

      // If the branch ref is gone (deleted after merge), fall back to head_sha
      if (merged === null && trail.head_sha) {
        merged = await isBranchMergedInto(repoFullName, pushedBranch, trail.head_sha, token)
      }

      if (!merged) continue

      // Verify this push actually merged the branch by checking it wasn't already
      // incorporated before this push. We only need to know whether ANY checkpoint
      // commit exists on the branch — the actual count doesn't matter — so an
      // existence check with LIMIT 1 is cheaper than COUNT(DISTINCT) over the
      // whole branch's checkpoint set.
      let hasCheckpoints = false
      try {
        hasCheckpoints = await db.checkpoints.branchHasCheckpointCommits(repoId, trail.branch)
      } catch {
        // Ignore errors
      }

      if (!isNewBranch && !hasCheckpoints) {
        const wasAlreadyIn = await isBranchMergedInto(repoFullName, beforeSha, trail.branch, token)
        if (wasAlreadyIn) continue
      }

      // Capture the merge-base and head SHAs so file diffs survive branch deletion.
      const headSha = await resolveBranchSha(repoFullName, trail.branch, token)

      let mergeBaseSha: string | null = null
      if (headSha && !isNewBranch) {
        mergeBaseSha = await getMergeBaseSha(repoFullName, beforeSha, headSha, token)
      }

      const now = new Date().toISOString()
      await db.trails.updateMetadata(repoId, trail.id, {
        status: "merged",
        merged_at: now,
        updated_at: now,
        ...(mergeBaseSha && { merge_base_sha: mergeBaseSha }),
        ...(headSha && { head_sha: headSha }),
      })

      console.log(
        `[trails-merge] merged trail=#${trail.number} repo=${repoFullName} branch=${trail.branch}`,
      )

      // Close shadow draft PR if one exists (leaves user-created PRs alone)
      if (trail.gh_pr_id) {
        try {
          await closeTrailPR(db, repoFullName, repoId, trail, token)
        } catch {
          // Non-critical — PR cleanup failure should not block merge
        }
      }
    } catch (err) {
      console.error(`[trails-merge] failed trail=#${trail.number} repo=${repoFullName}: ${err}`)
    }
  }
}

/**
 * Detect trail merges on push events. When a branch receives a push,
 * check if any trail's feature branch has been fully merged into it.
 */
async function processTrailMergeDetection(
  eventType: string,
  payload: Record<string, unknown>,
  db: Db,
  env: Env,
): Promise<void> {
  if (eventType !== "push") return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo?.full_name) return

  const ref = payload.ref as string | undefined
  if (!ref?.startsWith("refs/heads/")) return
  const branch = ref.replace("refs/heads/", "")

  // Skip special branches
  if (branch === CHECKPOINT_BRANCH) return

  // Skip branch deletions
  if (payload.deleted === true) return

  const repoFullName = repo.full_name as string
  const repoGithubId = (repo as Record<string, unknown>).id as number

  // Find the repo record for DB access
  const repoRecord = await db.repos.getByGithubId(repoGithubId)
  if (!repoRecord) return

  const installationId = await validateInstallation(
    payload,
    db,
    `Trail merge detection ${repoFullName}`,
  )
  if (installationId === null) return

  let token: string
  try {
    token = await getInstallationToken(
      installationId,
      { appId: env.GITHUB_CLIENT_ID, privateKey: env.GITHUB_APP_PRIVATE_KEY },
      env.ENTIRE_CACHE,
    )
  } catch {
    return
  }

  try {
    const before = (payload.before as string) || ""
    await checkAndMergeTrails(env, db, repoRecord.id, repoFullName, branch, before, token)
  } catch (err) {
    console.log(
      `[trails-merge] error repo=${repoFullName} branch=${branch} error=${err instanceof Error ? err.message : String(err)}`,
    )
  }
}

