    expect(getPullRequestState).not.toHaveBeenCalled()
    expect(closePullRequest).not.toHaveBeenCalled()
    expect(db.trails.updateMetadata).not.toHaveBeenCalled()
  })

  it("closes shadow draft PR and clears tracking", async () => {
    const trail = makeTrailRow({ gh_pr_id: 42 })
    vi.mocked(getPullRequestState).mockResolvedValueOnce(
      makePRState({ number: 42, draft: true, body: SHADOW_BODY }),
    )

    await closeTrailPR(db, "owner/repo", "repo-1", trail, "token")

    expect(closePullRequest).toHaveBeenCalledWith("owner/repo", 42, "token")
    expect(db.trails.updateMetadata).toHaveBeenCalledWith("repo-1", "uuid-1", { gh_pr_id: null })
  })

  it("does NOT close user-created PR but still clears tracking", async () => {
    const trail = makeTrailRow({ gh_pr_id: 50 })
    vi.mocked(getPullRequestState).mockResolvedValueOnce(
      makePRState({ number: 50, draft: false, body: USER_BODY }),
    )

    await closeTrailPR(db, "owner/repo", "repo-1", trail, "token")

    expect(closePullRequest).not.toHaveBeenCalled()
    expect(db.trails.updateMetadata).toHaveBeenCalledWith("repo-1", "uuid-1", { gh_pr_id: null })
  })

  it("closes a published (non-draft) shadow PR by its marker", async () => {
    // A shadow PR published at merge time (markPullRequestReady) is no longer a
    // draft; it must still be closed so abandoning the trail doesn't leak it.
    const trail = makeTrailRow({ gh_pr_id: 42 })
    vi.mocked(getPullRequestState).mockResolvedValueOnce(
      makePRState({ number: 42, draft: false, body: SHADOW_BODY }),
    )

    await closeTrailPR(db, "owner/repo", "repo-1", trail, "token")

    expect(closePullRequest).toHaveBeenCalledWith("owner/repo", 42, "token")
    expect(db.trails.updateMetadata).toHaveBeenCalledWith("repo-1", "uuid-1", { gh_pr_id: null })
  })

  it("does NOT close user-created draft PR (draft but no shadow marker in body)", async () => {
    const trail = makeTrailRow({ gh_pr_id: 55 })
    vi.mocked(getPullRequestState).mockResolvedValueOnce(
      makePRState({ number: 55, draft: true, body: USER_BODY }),
    )

    await closeTrailPR(db, "owner/repo", "repo-1", trail, "token")

    expect(closePullRequest).not.toHaveBeenCalled()
    expect(db.trails.updateMetadata).toHaveBeenCalledWith("repo-1", "uuid-1", { gh_pr_id: null })
  })

  it("clears tracking even when PR is already gone (404)", async () => {
    const trail = makeTrailRow({ gh_pr_id: 42 })
    vi.mocked(getPullRequestState).mockResolvedValueOnce(null)

    await closeTrailPR(db, "owner/repo", "repo-1", trail, "token")

    expect(closePullRequest).not.toHaveBeenCalled()
    expect(db.trails.updateMetadata).toHaveBeenCalledWith("repo-1", "uuid-1", { gh_pr_id: null })
  })
})

