describe("parseTrailNumber", () => {
  it("accepts a small positive integer", () => {
    expect(parseTrailNumber("1")).toBe(1)
    expect(parseTrailNumber("42")).toBe(42)
  })

  it("accepts the INT UNSIGNED maximum", () => {
    expect(parseTrailNumber("4294967295")).toBe(4_294_967_295)
  })

  it("rejects values past INT UNSIGNED max", () => {
    expect(parseTrailNumber("4294967296")).toBeNull()
    expect(parseTrailNumber("9999999999")).toBeNull()
  })

  it("rejects leading zeros so each trail has exactly one URL form", () => {
    expect(parseTrailNumber("042")).toBeNull()
    expect(parseTrailNumber("0042")).toBeNull()
    expect(parseTrailNumber("0")).toBeNull()
  })

  it("rejects non-decimal forms", () => {
    expect(parseTrailNumber("0x10")).toBeNull()
    expect(parseTrailNumber("1e5")).toBeNull()
    expect(parseTrailNumber("-1")).toBeNull()
    expect(parseTrailNumber("1.5")).toBeNull()
  })

  it("rejects whitespace", () => {
    expect(parseTrailNumber(" 42")).toBeNull()
    expect(parseTrailNumber("42 ")).toBeNull()
    expect(parseTrailNumber("4 2")).toBeNull()
  })

  it("rejects empty / non-numeric", () => {
    expect(parseTrailNumber("")).toBeNull()
    expect(parseTrailNumber("abc")).toBeNull()
    expect(parseTrailNumber("42abc")).toBeNull()
  })

  it("rejects > 10 digits even if numerically below max", () => {
    // "10000000000" is 10 zeros after a 1 → 11 digits, parses as 10_000_000_000
    expect(parseTrailNumber("10000000000")).toBeNull()
