async function resolveTrailTimelineCompareRefs(args: {
  row: TrailRow
  repo: Repo
  repoFullName: string
  token: string
}): Promise<{ base: string; head: string } | null> {
  const { row, repo, repoFullName, token } = args
  const historyBranch = getTrailHistoryBranch(row)
  const terminalSnapshotRefs =
    (row.status === "merged" || row.status === "closed") && row.merge_base_sha && row.head_sha
      ? { base: row.merge_base_sha, head: row.head_sha }
      : null
  if (terminalSnapshotRefs) return terminalSnapshotRefs
  if (!historyBranch) return null

  const baseRef = resolveBaseBranch(row, repo)
  try {
    const mergeBaseSha = await getMergeBaseSha(repoFullName, baseRef, historyBranch, token)
    if (mergeBaseSha) return { base: mergeBaseSha, head: historyBranch }
    console.warn(
      `Timeline merge base not found for trail #${row.number}; falling back to ${baseRef}...${historyBranch}`,
    )
  } catch (err) {
    console.warn(
      `Failed to resolve timeline merge base for trail #${row.number}; falling back to ${baseRef}:`,
      err,
    )
  }

  return { base: baseRef, head: historyBranch }
}

