/**
 * Find an existing open PR for the given head → base.
 */
export async function findOpenPullRequest(
  repoFullName: string,
  head: string,
  base: string,
  accessToken: string,
): Promise<{ number: number; draft: boolean } | null> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=open`,
    { headers: githubHeaders(accessToken) },
  )
  if (!response.ok) {
    response.body?.cancel()
    return null
  }
  const prs = await response.json<{ number: number; draft: boolean }[]>()
  const pr = prs[0]
  if (!pr) return null
  return { number: pr.number, draft: pr.draft }
}

function normalizePullRequestBranchRef(
  data:
    | {
        ref?: unknown
        repo?: { id?: unknown; full_name?: unknown } | null
      }
    | null
    | undefined,
): PullRequestBranchRef {
  return {
    ref: typeof data?.ref === "string" ? data.ref : "",
    repo: {
      id: typeof data?.repo?.id === "number" ? data.repo.id : null,
      full_name: typeof data?.repo?.full_name === "string" ? data.repo.full_name : null,
    },
  }
}

