  const pr = payload.pull_request as Record<string, unknown> | undefined
  if (!pr) return
  if (action === "opened" && pr.draft === true) return

  const installationId = await validateInstallation(payload, db, "Trail gh_pr_id link on PR open")
  if (installationId === null) return

  const repo = payload.repository as Record<string, unknown> | undefined
  if (!repo || typeof repo.id !== "number") return

  const repoGithubId = repo.id as number
  const prNumber = pr.number as number | undefined
  const head = pr.head as Record<string, unknown> | undefined
  const base = pr.base as Record<string, unknown> | undefined
  const headBranch = head?.ref as string | undefined
  const baseBranch = base?.ref as string | undefined
  const headRepo = head?.repo as { id?: unknown } | undefined
  const baseRepo = base?.repo as { id?: unknown } | undefined

  if (!prNumber || !headBranch || !baseBranch) return
  if (typeof headRepo?.id !== "number" || headRepo.id !== baseRepo?.id) return

  try {
    const repoRecord = await db.repos.getByGithubId(repoGithubId)
    if (!repoRecord) return

    const dbInstallationId = await db.installations.findIdByGitHubId(installationId)
    if (!dbInstallationId || repoRecord.installation_id !== dbInstallationId) return

    const trail = await db.trails.getByBranch(repoRecord.id, headBranch)
    if (!trail || isTerminalTrailStatus(trail.status)) return

    if (syncBaseRetarget) {
      if (trail.gh_pr_id !== prNumber || trail.base === baseBranch) return
      await db.trails.updateMetadata(repoRecord.id, trail.id, { base: baseBranch })
      return
    }

    if (trail.gh_pr_id && trail.gh_pr_id !== prNumber) return

    const metadata: { gh_pr_id?: number; base?: string } = {}
    if (!trail.gh_pr_id) metadata.gh_pr_id = prNumber
    if (trail.base !== baseBranch) metadata.base = baseBranch
    if (Object.keys(metadata).length === 0) return

    await db.trails.updateMetadata(repoRecord.id, trail.id, metadata)
  } catch (err) {
    console.error(
      `[trails-pr-id-link] failed repo=${repo.full_name as string} pr=#${prNumber}: ${err instanceof Error ? err.message : String(err)}`,
    )
    })
  } catch (err) {
    logCheckpointMetric("git_source_ingest_failed", {
      repo: repoFullName,
      branch,
      error: err instanceof Error ? err.message : String(err),
    })
    try {
      await enqueueReconcileBranch(env, {
        repoId: repoRecord.id,
        branch,
        reason: "failure",
        source: "webhook:processCommitPushEvent",
      })
    } catch {
      // best-effort
    }
    throw err
  }
}

