export interface ResolveCommitResponse {
  commit_sha: string
  branches: string[]
  default_branch: string | null
  suggested_branch: string | null
  commit: CommitInfo | null
  repo_full_name: string
}

export async function fetchRepoCommits(
  org: string,
  repo: string,
  branch: string = "main",
  options?: {
    source?: "github"
    since?: string
    until?: string
    limit?: number
    offset?: number
    cursor?: string
  },
): Promise<RepoCommitsResponse> {
  const params = new URLSearchParams({ branch })
  if (options?.source) {
    params.set("source", options.source)
  }
  if (options?.since) {
    params.set("since", options.since)
  }
  if (options?.until) {
    params.set("until", options.until)
  }
  if (options?.limit) {
    params.set("limit", String(options.limit))
  }
  if (options?.offset) {
    params.set("offset", String(options.offset))
  }
  if (options?.cursor) {
    params.set("cursor", options.cursor)
  }
  return request<RepoCommitsResponse>(`/api/v1/cache/${org}/${repo}/commits?${params.toString()}`)
}

export async function resolveCommit(
  org: string,
  repo: string,
  commitSha: string,
): Promise<ResolveCommitResponse> {
  return request<ResolveCommitResponse>(
    `/api/v1/cache/${org}/${repo}/commits/resolve/${encodeURIComponent(commitSha)}`,
  )
}

