import { createFileRoute, notFound } from "@tanstack/react-router"

import { TrailDetailPage } from "@/domains/platform/trails/pages/TrailDetailPage"

// Mirrors the API's parseTrailNumber: positive integer, ≤ INT UNSIGNED max,
// no leading zeros so each trail has exactly one canonical URL form.
const TRAIL_NUMBER_PATTERN = /^[1-9][0-9]{0,9}$/

function parseTrailNumberOrThrow(raw: string): number {
  if (!TRAIL_NUMBER_PATTERN.test(raw)) {
    // Reject /trails/abc, /trails/042, /trails/-1 at the route boundary
    // so NaN never reaches the API and the user gets a clean 404 instead
    // of "Failed to load trail details."
    throw notFound()
  }
  const n = Number(raw)
  if (n > 4_294_967_295) throw notFound()
  return n
}

export const Route = createFileRoute("/_app/_repo/gh/$org/$repo/trails/$number/{-$slug}")({
  component: TrailDetailPageRoute,
  beforeLoad: ({ params }) => {
    parseTrailNumberOrThrow(params.number)
  },
  validateSearch: (search: Record<string, unknown>) => ({
    tab: (search.tab as string) || undefined,
    mode: (search.mode as string) || undefined,
    view: search.view === "diff" || search.diff === "drawer" ? "diff" : undefined,
    file: (search.file as string) || undefined,
  }),
})

function TrailDetailPageRoute() {
  const { org, repo, number, slug } = Route.useParams()
  const { tab, mode, view, file } = Route.useSearch()
  // beforeLoad already validated the format — Number() always succeeds here.
  const parsedNumber = parseTrailNumberOrThrow(number)
  return (
    <TrailDetailPage
      org={org}
      repo={repo}
      number={parsedNumber}
      slug={slug}
      initialTab={tab}
      initialMode={mode}
      initialView={view}
      initialFile={file}
    />
  )
}

