export interface TrailsQueryParams {
  limit?: number
  offset?: number
  status?: string
  status_not?: string
  priority?: string
  priority_not?: string
  type?: string
  type_not?: string
  author?: string
  author_not?: string
  assignee?: string
  assignee_not?: string
  search?: string
}

export async function fetchTrails(
  org: string,
  repo: string,
  params?: TrailsQueryParams,
): Promise<TrailsResponse> {
  const searchParams = new URLSearchParams()
  if (params) {
    for (const [key, value] of Object.entries(params)) {
      if (value !== undefined && value !== null && value !== "") {
        searchParams.set(key, String(value))
      }
    }
  }
  const qs = searchParams.toString()
  const url = `${trailRepoApiPath(org, repo)}${qs ? `?${qs}` : ""}`
  return request<TrailsResponse>(url)
}

