/**
 * Derive the only user-facing approval state we show now: approved.
 * Pending and requested-changes are not surfaced as separate Trail states.
 */
function deriveApprovalStatus(reviewers?: { status: string }[]): "approved" | null {
  if (!reviewers?.length) return null
  const decided = reviewers.filter((r) => r.status !== "pending")
  if (decided.length === 0) return null
  if (decided.every((r) => r.status === "approved")) return "approved"
  return null
}

/**
 * Whether the current viewer has already submitted an approval. Approving is a
 * per-reviewer action: one person approving must not hide the Approve button
 * from everyone else, so we gate the button on the viewer's own decision rather
 * than the trail's aggregate approval status. When the login is unknown we treat
 * the viewer as not-yet-approved to preserve the previous permissive behavior.
 */
export function hasViewerApproved(
  reviewers: { login: string; status: string }[] | undefined,
  viewerLogin: string | null | undefined,
): boolean {
  if (!viewerLogin) return false
  return (reviewers ?? []).some((r) => r.login === viewerLogin && r.status === "approved")
}

/** Count of reviewers whose latest decision is an approval. */
export function countApprovals(reviewers?: { status: string }[]): number {
  return (reviewers ?? []).filter((r) => r.status === "approved").length
}

function isBranchOutOfDate(mergeability?: TrailMergeability) {
  return (mergeability?.behind_by ?? 0) > 0
}

function isBranchFreshnessUnknown(mergeability?: TrailMergeability) {
  return mergeability?.comparison_status === "unknown"
}

/**
 * Whether the trail branch has commits ahead of base. Single source of truth:
 * the durable `has_code_changes` flag (computed server-side from already-synced
 * commits), so it never depends on a live, viewer-token compare that can fail
 * and silently report zero.
 */
function trailHasCodeChanges(trail?: Pick<TrailDetail, "has_code_changes"> | null): boolean {
  return !!trail?.has_code_changes
}

/**
 * Whether the approval gate has passed. Prefers the server-computed gate from
 * mergeability and falls back to the locally-known reviewer decisions. Shared by
 * the gate list and the sidebar lifecycle status so the two never drift.
 */
function deriveTrailApprovalPassed(
  trail: Pick<TrailDetail, "status" | "reviewers">,
  mergeability?: TrailMergeability,
): boolean {
  if (trail.status === "merged") return true
  if (mergeability) return isApprovalGatePassed(mergeability)
  return deriveApprovalStatus(trail.reviewers) === "approved"
}

function getThreadReadStorageKey({
  username,
  org,
  repo,
  number,
}: {
  username?: string | null
  org: string
  repo: string
  number: number
}) {
  return `entire:trail-thread:last-read:${username ?? "anonymous"}:${org}/${repo}/${number}`
}

function readThreadTimestamp(key: string): number | null {
  try {
    const value = window.localStorage.getItem(key)
    if (!value) return null
    const timestamp = Number(value)
    return Number.isFinite(timestamp) ? timestamp : null
  } catch {
    return null
  }
}

function writeThreadTimestamp(key: string, timestamp: number) {
  try {
    window.localStorage.setItem(key, String(timestamp))
  } catch {
    // Ignore storage failures; unread state is a best-effort local affordance.
  }
}

function getIncomingThreadTimestamps(threads: TrailThreadSummary[], username?: string | null) {
  const timestamps: number[] = []

  for (const thread of threads) {
    if (!thread.last_message_at || thread.last_message_author === username) continue
    const timestamp = Date.parse(thread.last_message_at)
    if (Number.isFinite(timestamp)) timestamps.push(timestamp)
  }

  return timestamps
}

function getLatestThreadTimestamp(timestamps: number[]) {
  return timestamps.length > 0 ? Math.max(...timestamps) : null
}

