import { getApiBaseUrl } from "@/lib/api/base-url"

const API_BASE_URL = getApiBaseUrl()

type RequestOptions = RequestInit & { token?: string }

export class ApiError extends Error {
  status: number
  constructor(message: string, status: number) {
    super(message)
    this.name = "ApiError"
    this.status = status
  }
}

// Read a cookie value by name
export function getCookie(name: string): string | null {
  const match = document.cookie.match(new RegExp(`(^|; )${name}=([^;]*)`))
  return match ? match[2] : null
}

/**
 * Whether an error means the user must re-authenticate. Any 401 qualifies (by
 * status, not message); 403 only for the specific GitHub-token messages below
 * (admin/CSRF 403s must not trigger re-auth). The message fallback covers
 * status-less inputs (e.g. PostHog payloads rebuilt from a message string).
 */
export function isAuthError(error: unknown): boolean {
  if (!error) return false
  if (error instanceof ApiError && error.status === 401) return true
  const rawMessage = (error as { message?: unknown }).message
  const message = typeof rawMessage === "string" ? rawMessage.toLowerCase() : ""
  return (
    message === "not authenticated" ||
    message === "session expired" ||
    message === "github token required for this operation" ||
    message === "github token expired"
  )
}

/**
 * Normalize a generated SDK error (the raw response body it throws) into an
 * `ApiError` carrying the HTTP status, so SDK failures match the `ApiError`
 * contract the rest of the app classifies on. `response` is `undefined` on
 * network failures.
 */
export function toApiError(error: unknown, response: Response | undefined): ApiError {
  if (error instanceof ApiError) return error
  const fallback =
    response?.statusText || (error instanceof Error ? error.message : "Request failed")
  const message = normalizeErrorMessage(error, fallback)
  return new ApiError(message, response?.status ?? 0)
}

/** Genuine repository-level 404 (not a transient/5xx error that merely mentions a repo). */
export function isRepoNotFoundError(error: Error | null | undefined): boolean {
  return (
    error instanceof ApiError && error.status === 404 && /repository not found/i.test(error.message)
  )
}

export function normalizeErrorMessage(data: unknown, fallback: string): string {
  if (data && typeof data === "object") {
    if ("error" in data && typeof (data as { error?: unknown }).error === "string") {
      return (data as { error: string }).error
    }

    if ("errors" in data && Array.isArray((data as { errors?: unknown }).errors)) {
      const errors = (data as { errors: unknown[] }).errors.filter(
        (message): message is string => typeof message === "string",
      )

      if (errors.length > 0) {
        return errors.join(", ")
      }
    }
  }

  return fallback
}

export async function request<T>(endpoint: string, options: RequestOptions = {}): Promise<T> {
  const { token: _token, headers, ...rest } = options
  const requestHeaders = new Headers(headers ?? {})

  if (rest.body && !requestHeaders.has("Content-Type")) {
    requestHeaders.set("Content-Type", "application/json")
  }

  // Add CSRF token header for state-changing requests (double-submit cookie pattern)
  const method = (rest.method ?? "GET").toUpperCase()
  if (["POST", "PUT", "DELETE", "PATCH"].includes(method)) {
    const csrfToken = getCookie("csrf")
    if (csrfToken) {
      requestHeaders.set("X-CSRF-Token", csrfToken)
    }
  }

  // traceparent header is added automatically by @opentelemetry/instrumentation-fetch

  const response = await fetch(`${API_BASE_URL}${endpoint}`, {
    ...rest,
    headers: requestHeaders,
    credentials: "include",
  })

  let data: unknown = null
  const contentType = response.headers.get("Content-Type") ?? ""

  if (contentType.includes("application/json")) {
    data = await response.json().catch(() => null)
  }

  if (!response.ok) {
    const message = normalizeErrorMessage(data, response.statusText || "Request failed")
    throw new ApiError(message, response.status)
  }

  return data as T
}

