export function useCreateTrailCiPrMutation(org: string, repo: string, number: number) {
  const queryClient = useQueryClient()

  const trailChecksQueryKey = ["github", "trail-checks", org, repo, number]

  return useMutation<CreateTrailCiPrResponse, Error, void>({
    mutationFn: () => createTrailCiPr(org, repo, number),
    onSuccess: (result) => {
      // Only patch the cache when the response carries a valid PR number.
      // request() casts the JSON without runtime validation, so an unexpected
      // shape must not write an invalid `ci_pr.number` into the cache — the
      // invalidation below refetches the authoritative /checks state anyway.
      if (typeof result?.pr_number === "number") {
        const prNumber = result.pr_number
        queryClient.setQueryData<TrailChecksStatus>(trailChecksQueryKey, (previous) => ({
          state: previous?.state ?? "none",
          head_sha: previous?.head_sha ?? null,
          total_count: previous?.total_count ?? 0,
          checks: previous?.checks ?? [],
          permission_error: previous?.permission_error,
          conflict: previous?.conflict,
          automation: previous?.automation ?? null,
          ci_pr: { number: prNumber, can_create: false },
        }))
      }
      queryClient.invalidateQueries({
        queryKey: trailChecksQueryKey,
      })
      queryClient.invalidateQueries({
        queryKey: ["github", "trails", org, repo, number, "mergeability"],
      })
    },
    onError: (error) => {
      console.error("createTrailCiPr failed", error)
    },
  })
}

