        github_login: authUser.github_login,
        discovery_enabled: authUser.discovery_enabled,
        is_admin: authUser.is_admin,
        is_entirehq_member: authUser.is_entirehq_member,
        $created_at: authUser.created_at,
      })
    },
    [posthog],
  )

