    (authUser: AuthUser) => {
      setUser(authUser)
      setIsAuthenticated(true)
      setShouldCheckSession(false)
      queryClient.setQueryData(["auth", "me"], authUser)
      seedRepoPreferencesCache(authUser)
      identifyPostHogUser(authUser)
    },
    [identifyPostHogUser, queryClient, seedRepoPreferencesCache],
  )

  const clearAuth = useCallback(() => {
    setUser(null)
    setIsAuthenticated(false)
    setShouldCheckSession(false)
    queryClient.removeQueries({ queryKey: ["auth"] })
    queryClient.cancelQueries({ queryKey: ["auth"] })
    queryClient.removeQueries({ queryKey: getApiV1PreferencesReposQueryKey() })
    queryClient.removeQueries({ queryKey: ["preferences"] })
  }, [queryClient])

  // Update user data without re-fetching (e.g. after toggling admin)
  const updateUser = useCallback(
    (authUser: AuthUser) => {
      setUser(authUser)
      queryClient.setQueryData(["auth", "me"], authUser)
      seedRepoPreferencesCache(authUser)
      identifyPostHogUser(authUser)
    },
    [identifyPostHogUser, queryClient, seedRepoPreferencesCache],
  )

  // GitHub OAuth login - just redirect, no mutation needed
  const login = useCallback((next?: string) => {
    startLogin(next)
