        return
      }

      completeLogout(redirectTo)
    },
    [completeLogout, posthog],
  )

  // Check if we have an active session on mount (only once)
  const meQuery = useQuery<AuthUser, Error>({
    queryKey: ["auth", "me"],
    queryFn: fetchCurrentUser,
    enabled: shouldCheckSession,
    retry: false,
    staleTime: Infinity,
    refetchOnMount: false,
    refetchOnWindowFocus: false,
  })

