  useEffect(() => {
    if (meQuery.data && shouldCheckSession) {
      persistAuth(meQuery.data)
    } else if (meQuery.isError && shouldCheckSession) {
      clearAuth()
    }
  }, [meQuery.data, meQuery.isError, shouldCheckSession, persistAuth, clearAuth])

  const isVerifying = shouldCheckSession || meQuery.isFetching

  const value = useMemo<AuthContextValue>(
    () => ({
      isAuthenticated,
      user,
      login,
      logout,
      updateUser,
      isLoggingIn: false, // No loading state for redirect-based auth
      loginError: null, // Errors handled by OAuth flow
      isVerifying,
    }),
    [isAuthenticated, user, login, logout, updateUser, isVerifying],
  )

