export interface RepoPreferenceItem {
  repo_id: string
  full_name: string
  runners_enabled: boolean
  trails_enabled: boolean
}

export interface AuthUser {
  id: string
  github_login: string
  discovery_enabled: boolean
  is_admin: boolean
  is_entirehq_member: boolean
  created_at: string
  repo_preferences: {
    pinned: RepoPreferenceItem[]
    recent: RepoPreferenceItem[]
  }
  search_enabled: boolean
  feature_flags: Partial<Record<FeatureFlagKey, boolean>>
  waitlisted?: boolean
