const LOCAL_DEV_ADMIN_BOOTSTRAP_PREFIX = "local-dev-admin-bootstrap:"

function shouldBootstrapLocalDevAdmin(user: AuthUser): boolean {
  // A waitlisted session is default-denied on /api/v1, so the bootstrap-admin
  // POST would 403 and break fetchCurrentUser (and the wait page's poll).
  if (!import.meta.env.DEV || user.is_admin || user.waitlisted) {
    return false
  }

  try {
    return localStorage.getItem(`${LOCAL_DEV_ADMIN_BOOTSTRAP_PREFIX}${user.id}`) === null
  } catch {
    return false
  }
}

function markLocalDevAdminBootstrapped(userId: string): void {
  try {
    localStorage.setItem(`${LOCAL_DEV_ADMIN_BOOTSTRAP_PREFIX}${userId}`, "1")
  } catch {
    // Ignore storage failures in development-only bootstrap flow.
  }
}

/**
 * Fetch current authenticated user
 */
export async function fetchCurrentUser(): Promise<AuthUser> {
  const user = await request<AuthUser>("/api/v1/auth/me")

  if (!shouldBootstrapLocalDevAdmin(user)) {
    return user
  }

  await request<{ is_admin: boolean }>("/api/v1/dev/auth/bootstrap-admin", {
    method: "POST",
  })
  markLocalDevAdminBootstrapped(user.id)
  return request<AuthUser>("/api/v1/auth/me")
}

/**
 * Initiate the OAuth login flow. The API picks the IdP (GitHub or entire-core)
 * based on its own runtime config, so the frontend does not need to know which
 * provider is active.
 */
export function startLogin(next?: string): void {
  const apiUrl = getApiBaseUrl()
  const params = new URLSearchParams()
  const sanitizedNext = sanitizeRelativeRedirectPath(next)

  if (sanitizedNext) {
    params.set("next", sanitizedNext)
  }

  const query = params.toString()
  window.location.href = `${apiUrl}/auth/start${query ? `?${query}` : ""}`
}

/**
 * Get the URL for initiating GitHub App installation flow
 */
export function getGitHubInstallationUrl(): string {
  const apiUrl = getApiBaseUrl()
  return `${apiUrl}/auth/github/start-installation`
}

/**
 * Get the URL for re-authorizing GitHub (a fresh OAuth exchange). Used to recover
 * access to a SAML/SSO-enforced org whose repos GitHub hid from the stored token —
 * unlike a plain re-login, this re-mints an SSO-authorized token.
 */
export function getGitHubConnectUrl(next?: string): string {
  const apiUrl = getApiBaseUrl()
  const sanitizedNext = sanitizeRelativeRedirectPath(next)
  const query = sanitizedNext ? `?${new URLSearchParams({ next: sanitizedNext }).toString()}` : ""
  return `${apiUrl}/auth/github/connect/start${query}`
}

/**
 * Logout the current user
 */
export async function logoutRequest(): Promise<void> {
  await request<{ success: boolean }>("/api/v1/auth/logout", {
    method: "POST",
  })
}

/**
 * Toggle admin status for entirehq org members
 */
export async function toggleAdmin(): Promise<AuthUser> {
  return request<AuthUser>("/api/v1/auth/toggle-admin", {
    method: "POST",
  })
}

