      }
    }

    const currentAdminStatus = isAdmin(c.env, user.is_admin)
    const newAdminStatus = !currentAdminStatus
    await db.users.setAdmin(userId, newAdminStatus)

    try {
      await c.env.ENTIRE_CACHE.delete(`user:${userId}`)
    } catch (err) {
      console.error(`Failed to invalidate user cache for ${userId}:`, err)
    }

    const personProperties: PostHogPersonProperties = {
      github_login: user.github_login,
      discovery_enabled: user.discovery_enabled,
      is_admin: newAdminStatus,
      is_entirehq_member: isEntireHqMember,
    }

