// Session management using KV storage

import type { Session } from "../types"

const SESSION_TTL = 60 * 60 * 24 * 7 // 7 days in seconds

// Create a new session
export async function createSession(kv: KVNamespace, userId: string): Promise<string> {
  const token = crypto.randomUUID()

  const session: Session = {
    userId,
    expiresAt: Date.now() + SESSION_TTL * 1000,
  }

  await kv.put(`session:${token}`, JSON.stringify(session), {
    expirationTtl: SESSION_TTL,
  })

  return token
}

// Get session by token
export async function getSession(kv: KVNamespace, token: string): Promise<Session | null> {
  const data = await kv.get<Session>(`session:${token}`, "json")

  if (!data) {
    return null
  }

  // Check if expired (belt and suspenders with KV TTL)
  if (Date.now() > data.expiresAt) {
    await kv.delete(`session:${token}`)
    return null
  }

  return data
}

// Delete session (logout)
export async function deleteSession(kv: KVNamespace, token: string): Promise<void> {
  await kv.delete(`session:${token}`)
}

