import type { QueryClient } from "@tanstack/react-query"
import { notFound, redirect } from "@tanstack/react-router"

import { redirectToLogin, shouldRedirectToLogin } from "@/domains/platform/auth/loginRedirect"
import { type BranchesResponse, fetchBranches } from "@/domains/platform/checkpoints/api"
import {
  branchesQueryOptions,
  checkpointStatusQueryOptions,
  infiniteCommitsQueryOptions,
} from "@/domains/platform/checkpoints/hooks/useCommitsQuery"
import { ApiError } from "@/lib/api"

export const GH_PATH_PREFIX = "/gh"

function buildCommitsHref(pathPrefix: string, org: string, repo: string, branch: string) {
  return `${pathPrefix}/${org}/${repo}/commits/${encodeURIComponent(branch)}`
}

async function ensureRepoBranchesOrThrowNotFound(
  queryClient: QueryClient,
  org: string,
  repo: string,
) {
  try {
    return await queryClient.ensureQueryData(branchesQueryOptions(org, repo))
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) {
      throw notFound()
    }
    throw error
  }
}

async function ensureBranchListAccessible({
  context,
  org,
  repo,
  branch,
  pathPrefix,
}: {
  context: { queryClient: QueryClient }
  org: string
  repo: string
  branch: string
  pathPrefix: string
}) {
  const [statusResult, commitsResult] = await Promise.allSettled([
    context.queryClient.ensureQueryData(checkpointStatusQueryOptions(org, repo)),
    context.queryClient.ensureInfiniteQueryData(infiniteCommitsQueryOptions(org, repo, branch)),
  ])

  if (statusResult.status === "rejected") {
    const error = statusResult.reason
    if (error instanceof ApiError && error.status === 404) {
      throw notFound()
    }
    throw error
  }

  if (commitsResult.status === "rejected") {
    const error = commitsResult.reason
    if (error instanceof ApiError && error.status === 404) {
      const branchesData =
        context.queryClient.getQueryData<BranchesResponse>(["github", "branches", org, repo]) ??
        (await fetchBranches(org, repo).catch(() => null))

      if (branchesData) {
        const targetBranch = resolveRedirectBranch(branch, branchesData)

        if (targetBranch) {
          throw redirect({
            // eslint-disable-next-line @typescript-eslint/no-explicit-any
            to: buildCommitsHref(pathPrefix, org, repo, targetBranch) as any,
            replace: true,
          })
        }
      }

      throw notFound()
    }

    throw error
  }
}

/**
 * Determines the redirect target when a branch is not found.
 * Returns the branch to redirect to, or null if the request should 404.
 *
 * Only redirects when the missing branch matches the DB's stored default
 * (i.e., the system auto-navigated via a stale value). Random/typo branches 404.
 */
export function resolveRedirectBranch(
  branch: string,
  branchesData: { branches: string[]; default_branch: string; stored_default_branch: string },
): string | null {
  const isStaleDefault = branch === branchesData.stored_default_branch
  if (!isStaleDefault) return null

  if (branchesData.default_branch !== branch) {
    return branchesData.default_branch
  }

  return null
}

/**
 * Loader for /gh/$org/$repo/{section} — preloads branches and first-paint data
 * for the default-branch list page. Works for both authenticated and
 * unauthenticated users.
 */
export function repoIndexLoader(pathPrefix: string) {
  return async ({
    context,
    params,
  }: {
    context: { queryClient: QueryClient }
    params: { org: string; repo: string }
  }) => {
    const { org, repo } = params

    const branchesData = await ensureRepoBranchesOrThrowNotFound(context.queryClient, org, repo)

    await ensureBranchListAccessible({
      context,
      org,
      repo,
      branch: branchesData.default_branch,
      pathPrefix,
    })
  }
}

/**
 * Loader for repo-scoped routes that require repo access.
 * Throws to the repo route's notFoundComponent so inaccessible repos short-circuit
 * before the app shell mounts.
 */
export async function repoAccessLoader({
  context,
  params,
  location,
}: {
  context: { queryClient: QueryClient; auth?: { isAuthenticated: boolean } }
  params: { org: string; repo: string }
  location: { href?: string; pathname: string }
}) {
  const { org, repo } = params

  try {
    await context.queryClient.ensureQueryData(checkpointStatusQueryOptions(org, repo))
  } catch (error) {
    if (error instanceof ApiError && error.status === 404) {
      if (shouldRedirectToLogin({ auth: context.auth, error })) {
        throw redirectToLogin({ location })
      }

      throw notFound()
    }
    throw error
  }
}

/**
 * Loader for /gh/$org/$repo/{section}/$branch — preloads first-paint data for the
 * branch list page and handles stale-default-branch redirects.
 */
export function branchListLoader(pathPrefix: string) {
  return async ({
    context,
    params,
  }: {
    context: { queryClient: QueryClient }
    params: { org: string; repo: string; branch: string }
  }) => {
    const { org, repo, branch } = params
    await ensureBranchListAccessible({ context, org, repo, branch, pathPrefix })
  }
}

export async function repoShellAccessLoader({
  context,
  params,
  location,
  pathPrefix,
}: {
  context: { queryClient: QueryClient; auth?: { isAuthenticated: boolean } }
  params: { org: string; repo: string }
  location: { href?: string; pathname: string }
  pathPrefix: string
}) {
  const repoBasePath = `${pathPrefix}/${params.org}/${params.repo}`
  const repoSubpath = location.pathname.startsWith(repoBasePath)
    ? location.pathname.slice(repoBasePath.length)
    : ""

  // Session detail has its own access check because public-shared sessions
  // must render for logged-out viewers even when repo status is private.
  if (/^\/session\/[^/]+\/?$/.test(repoSubpath)) {
    return
  }

  await repoAccessLoader({ context, params, location })

  const commitsBranchMatch = repoSubpath.match(/^\/commits\/([^/]+)\/?$/)
  if (!commitsBranchMatch) {
    return
  }

  await ensureBranchListAccessible({
    context,
    org: params.org,
    repo: params.repo,
    branch: decodeURIComponent(commitsBranchMatch[1]),
    pathPrefix,
  })
}

