function getBranchUpToDateGate({
  trail,
  mergeability,
  onUpdateBranch,
  isUpdatingBranch,
  updateBranchErrorMessage,
}: {
  trail: TrailDetail
  mergeability?: TrailMergeability
  onUpdateBranch?: () => void
  isUpdatingBranch: boolean
  updateBranchErrorMessage: string | null
}): StatusBoxGate {
  const name = "Branch up to date"
  const base = trail.base || "main"

  if (trail.status === "merged") {
    return {
      name,
      detail: `Merged into ${base}`,
      tone: "success",
    }
  }

  if (!mergeability) {
    return {
      name,
      detail: "Checking branch",
      tone: "pending",
      active: trail.status !== "closed",
    }
  }

  if (isBranchFreshnessUnknown(mergeability)) {
    return {
      name,
      detail: "Could not verify branch freshness",
      tone: "pending",
    }
  }

  if (isBranchOutOfDate(mergeability)) {
    const behindBy = mergeability.behind_by
    return {
      name,
      detail:
        updateBranchErrorMessage ??
        `${behindBy} ${behindBy === 1 ? "commit" : "commits"} behind ${base}`,
      tone: updateBranchErrorMessage ? "failed" : "pending",
      active: isUpdatingBranch,
      action: onUpdateBranch ? (
        <Button
          type="button"
          size="small"
          variant="outline"
          onClick={onUpdateBranch}
          disabled={isUpdatingBranch}
        >
          {isUpdatingBranch ? "Updating\u2026" : "Update branch"}
        </Button>
      ) : undefined,
    }
  }

  return {
    name,
    detail: `Up to date with ${base}`,
    tone: "success",
  }
}

