trailRoutes.get(
  "/:host/:owner/:repo/:number/mergeability",
  describeRoute({
    tags: ["Trails"],
    summary: "Get merge readiness for a trail",
    responses: {
      200: {
        description: "Trail mergeability",
        content: { "application/json": { schema: resolver(trailMergeabilitySchema) } },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      409: {
        description: "Repository has no GitHub App installation",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      503: {
        description: "GitHub App token temporarily unavailable",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    // Use the installation token: mergeability is a read (checks + ahead/behind)
    // that doesn't act as the user, so a stale viewer token shouldn't break it.
    const ctx = await resolveTrailWithInstallationToken(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, trail: row, githubToken: token } = ctx

    try {
      if (!row.branch) {
        return c.json({
          approval_gate_passed: false,
          checks_passed: false,
          checks_status: "none",
          checks: [],
          behind_by: 0,
          comparison_status: "unknown",
          mergeable: false,
        } satisfies TrailMergeability)
      }

      const reviewers = Array.isArray(row.reviewers)
        ? (row.reviewers as unknown as TrailReviewer[])
        : []
      const approvalGatePassed =
        reviewers.length > 0 && reviewers.every((reviewer) => reviewer.status === "approved")

      let checksStatus: TrailMergeability["checks_status"] = "none"
      let checksPassed = true
      let checks: TrailMergeability["checks"] = []

      const headSha = await resolveBranchSha(repoFullName, row.branch, token)
      if (headSha) {
        const checkResult = await fetchCommitCheckStatus(repoFullName, headSha, token)
        checksStatus = checkResult.state
        checks = checkResult.checks
        checksPassed = checkResult.state === "success" || checkResult.state === "none"
      }

      const baseResolution = await resolveAndSyncActiveTrailBase({
        db,
        repo: repoAccess,
        repoFullName,
        trail: row,
        token,
      })
      const comparison = await compareBranchStatus(
        repoFullName,
        baseResolution.base,
        row.branch,
        token,
      )
      const comparisonStatus: TrailMergeability["comparison_status"] = comparison
        ? "available"
        : "unknown"
      const behindBy = comparison?.behind_by ?? 0

      return c.json({
        approval_gate_passed: approvalGatePassed,
        checks_passed: checksPassed,
        checks_status: checksStatus,
        checks,
        behind_by: behindBy,
        comparison_status: comparisonStatus,
        mergeable:
          approvalGatePassed && checksPassed && comparisonStatus === "available" && behindBy === 0,
      } satisfies TrailMergeability)
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to check mergeability for trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to check mergeability" }, 500)
    }
  },
)

