  isUpdatingBranch: boolean
  updateBranchErrorMessage: string | null
}): StatusBoxGate {
  const name = "Branch up to date"
  const base = trail.base || "main"

  if (trail.status === "merged") {
    return {
      name,
      detail: `Merged into ${base}`,
      tone: "success",
    }
  }

  if (!mergeability && !isMergeabilityError) {
    return {
      name,
      detail: "Checking branch",
      tone: "pending",
      active: trail.status !== "closed",
