codeReviewRoutes.patch(
  "/trails/:trail_id/reviews/:id/comments/:comment_id",
  resourceRouteDoc(
    "Patch a review comment",
    "Updates body/severity/confidence/status. status_reason is required when transitioning into resolved or dismissed.",
    {
      requestBody: jsonBody(reviewCommentPatchJsonSchema),
      responses: {
        200: {
          description: "Updated review comment",
          content: { "application/json": { schema: resolver(reviewCommentResponseSchema) } },
        },
      },
    },
  ),
  async (c) => {
    const reviewId = c.req.param("id")
    const commentId = c.req.param("comment_id")
    const db = getDb(c.env)
    const existing = await db.codeReview.getReviewCommentById(commentId)
    if (!existing || existing.review_id !== reviewId) return notFound(c, "comment not found")
    const pathMismatch = requirePathTrailMatch(c, existing.trail_id, "comment not found")
    if (pathMismatch) return pathMismatch
    // Public visibility is not enough for mutations.
    const access = await resolveTrailAccess(c, existing.trail_id)
    if (access instanceof Response) return access
    if (!access.has_membership) {
      return errorEnvelope(c, 403, "forbidden", "repository membership required")
    }
    let body: unknown
    try {
      body = await c.req.json()
    } catch {
      return badRequest(c, "invalid JSON body")
    }
    if (!body || typeof body !== "object") return badRequest(c, "body must be an object")
    const b = body as Record<string, unknown>
    if (b.status !== undefined && !VALID_STATUSES.includes(b.status as ReviewCommentStatus))
      return badRequest(c, "status invalid")
    if (
      b.severity !== undefined &&
      b.severity !== null &&
      !VALID_SEVERITIES.includes(b.severity as ReviewCommentSeverity)
    )
      return badRequest(c, "severity invalid")
    if (
      b.status_reason !== undefined &&
      b.status_reason !== null &&
      typeof b.status_reason !== "string"
    ) {
      return badRequest(c, "status_reason must be a string or null")
    }
    if (b.confidence !== undefined && b.confidence !== null && !isValidConfidence(b.confidence)) {
      return badRequest(c, "confidence must be a number between 0 and 1")
    }
    const nextStatus = (b.status as ReviewCommentStatus | undefined) ?? existing.status
    const suppliedStatusReason = b.status_reason as string | null | undefined
    const nextStatusReason =
      suppliedStatusReason !== undefined ? suppliedStatusReason : existing.status_reason
    const nextStatusIsJudgment = nextStatus === "resolved" || nextStatus === "dismissed"
    const isEnteringJudgmentStatus =
      b.status !== undefined && b.status !== existing.status && nextStatusIsJudgment
    const isEditingJudgmentReason = suppliedStatusReason !== undefined && nextStatusIsJudgment
    if (
      (isEnteringJudgmentStatus || isEditingJudgmentReason) &&
      (nextStatusReason === null || nextStatusReason.trim().length === 0)
    ) {
      return badRequest(c, "status_reason is required when resolving or dismissing a comment")
    }
    let comment
    try {
      comment = await db.codeReview.updateReviewComment(commentId, actor(c), {
        body: b.body as string | null | undefined,
        status: b.status as ReviewCommentStatus | undefined,
        status_reason: b.status_reason as string | null | undefined,
        severity: b.severity as ReviewCommentSeverity | null | undefined,
        confidence:
          b.confidence === null ? null : isValidConfidence(b.confidence) ? b.confidence : undefined,
      })
    } catch (err) {
      if (
        err instanceof Error &&
        err.message === "status_reason is required when resolving or dismissing a comment"
      ) {
        return badRequest(c, err.message)
      }
      throw err
    }
    if (!comment) return notFound(c, "comment not found")
    return c.json(comment)
  },
)

