// Idempotency is scoped by actor, route, key, and request body hash.
async function withIdempotency(
  c: Cx,
  routeKey: string,
  handler: () => Promise<Response>,
): Promise<Response> {
  const key = c.req.header("Idempotency-Key")
  if (!key) return handler()
  if (key.length > 255) return badRequest(c, "Idempotency-Key must not exceed 255 characters")
