  // key order or whitespace would otherwise hash differently and trip
  // `idempotency_key_conflict` on semantically-identical inputs. Falls
  // back to the raw bytes for non-JSON / empty bodies (canonicalize
  // throws on those — that's fine, raw is the right thing to hash).
  let toHash = rawBody
  if (rawBody.length > 0) {
    try {
      toHash = canonicalize(JSON.parse(rawBody))
    } catch {
      // Non-JSON body (or invalid JSON) — hash the raw bytes. The schema
      // parse below will reject malformed JSON with 400 anyway.
    }
  }
  const requestHash = await sha256Hex(toHash)
  const slot = {
    actor_id: actorId,
    route_key: routeKey,
    idempotency_key: key,
    request_hash: requestHash,
  }

  const safeRelease = async () => {
    try {
      await db.codeReview.releaseIdempotency(slot)
    } catch (err) {
      console.error(
        `[idempotency] release failed for ${routeKey}: ${err instanceof Error ? err.message : String(err)}`,
      )
    }
  }

  const acquired = await db.codeReview.claimIdempotency(slot)
  if (!acquired) {
    const cached = await db.codeReview.lookupIdempotency(slot)
    if (cached?.request_hash_mismatch) {
      return c.json(
        {
          error: {
            code: "idempotency_key_conflict",
            message: "Idempotency-Key already used with a different request body",
            field: null,
            retryable: false,
          },
        },
        409,
      )
    }
    if (cached && cached.response_status !== null && cached.response_body !== null) {
      return new Response(cached.response_body, {
        status: cached.response_status,
        headers: { "content-type": "application/json" },
      })
    }
    return c.json(
      {
        error: {
          code: "idempotency_in_flight",
          message: "request in flight, retry shortly",
          field: null,
          retryable: true,
        },
      },
      409,
    )
  }

  let response: Response
  try {
    response = await handler()
  } catch (err) {
    await safeRelease()
    throw err
  }
  // Cache successful responses only.
  if (response.status < 200 || response.status >= 400) {
    await safeRelease()
    return response
  }
  let body: string
  try {
    body = await response.clone().text()
  } catch (err) {
    console.error(
