    await safeRelease()
    return response
  }
  try {
    await db.codeReview.completeIdempotency({
      ...slot,
      response_status: response.status,
      response_body: body,
    })
  } catch (err) {
    console.error(
      `[idempotency] complete failed for ${routeKey}: ${err instanceof Error ? err.message : String(err)}`,
    )
    await safeRelease()
  }
  return response
}

// Trail access returns 404 on denial to avoid repo fishing.
interface TrailAccess {
  trail_id: string
  repo_id: string
  repo_full_name: string
  has_membership: boolean
}

async function resolveTrailAccess(c: Cx, trailId: string): Promise<TrailAccess | Response> {
  if (!isValidUuid(trailId)) {
    return badRequest(c, "invalid trail_id")
  }
  const userId = actor(c)
  const kysely = getKysely(c.env)
  const row = await kysely
    .selectFrom("repo_trails")
    .innerJoin("repos", "repos.id", "repo_trails.repo_id")
    .leftJoin("user_repos", (join) =>
      join.onRef("user_repos.repo_id", "=", "repos.id").on("user_repos.user_id", "=", userId),
    )
    .select([
      "repo_trails.id as trail_id",
      "repo_trails.repo_id as repo_id",
      "repos.full_name as repo_full_name",
      "repos.is_private as repo_is_private",
      "user_repos.user_id as access_user_id",
    ])
    .where("repo_trails.id", "=", trailId)
    .executeTakeFirst()
  if (!row) return notFound(c, "trail not found")
  const hasMembership = row.access_user_id != null
  const isPublic = !row.repo_is_private
  if (!hasMembership && !isPublic) {
    return notFound(c, "trail not found")
  }
  return {
    trail_id: row.trail_id,
    repo_id: row.repo_id,
    repo_full_name: row.repo_full_name,
    has_membership: hasMembership,
  }
}

