// Pre-built once: every table's DELETE in one round-trip via multipleStatements.
// The FK_CHECKS toggle is intentionally outside this batch — see resetMySQLDatabase.
const DELETES_SQL = TEST_TABLES.map((t) => `DELETE FROM ${t}`).join("; ")

/** Delete all rows for test isolation. Three round-trips: FK off, batched DELETEs, FK on.
 *  FK re-enable runs in `finally` so a failed DELETE can't strand a connection with
 *  FK_CHECKS=0, which would silently mask FK violations in a subsequent test. */
export async function resetMySQLDatabase(db: Kysely<DB>): Promise<void> {
  await sql`SET FOREIGN_KEY_CHECKS = 0`.execute(db)
  try {
    await sql.raw(DELETES_SQL).execute(db)
    // Per-trail event sequence rows are created lazily by allocateEventId,
    // so nothing to re-seed here. The DELETE above clears them along with
    // the trails they reference.
  } finally {
    await sql`SET FOREIGN_KEY_CHECKS = 1`.execute(db)
  }
}

