async function resolveAndSyncWebhookTrailBase(args: {
  db: Db
  repoId: string
  repoFullName: string
  repoDefaultBranch: string
  trail: TrailRow
  token: string
}): Promise<string> {
  const resolution = await resolveActiveTrailBase({
    repoFullName: args.repoFullName,
    repo: { default_branch: args.repoDefaultBranch },
    trail: args.trail,
    accessToken: args.token,
    fetchPullRequestState: getPullRequestState,
  })

  if (resolution.source === "pull_request") {
    const metadata = buildTrailBaseSyncMetadata(args.trail, resolution.base)
    if (metadata) {
      await args.db.trails.updateMetadata(args.repoId, args.trail.id, metadata)
      args.trail.base = resolution.base
    }
  }

  return resolution.base
}

function shouldCheckTrailMergeForPushedBranch(
  trail: TrailRow,
  repoDefaultBranch: string,
  pushedBranch: string,
): boolean {
  const storedBase = resolveBaseBranch(trail, { default_branch: repoDefaultBranch })
  if (storedBase === pushedBranch) return true

  // Older linked stacked trails may still store the repo default as their base
  // until the PR target is synced. Resolve those candidates, but do not fetch
  // PR state for every linked trail on every unrelated branch push.
  return Boolean(trail.gh_pr_id && storedBase === repoDefaultBranch)
}

