export function getTrailHistoryBranch(
  row: Pick<TrailRow, "branch" | "original_branch">,
): string | null {
  return row.branch ?? row.original_branch ?? null
}

function buildCiPrStatus(prNumber: number | null, canCreate: boolean): TrailCiPullRequestStatus {
  return { number: prNumber, can_create: canCreate && prNumber === null }
}

async function resolveAndSyncActiveTrailBase(args: {
  db: Db
  repo: Repo
  repoFullName: string
  trail: TrailRow
  token: string
}) {
  const resolution = await resolveActiveTrailBase({
    repoFullName: args.repoFullName,
    repo: args.repo,
    trail: args.trail,
    accessToken: args.token,
    fetchPullRequestState: getPullRequestState,
  })

  if (resolution.source === "pull_request") {
    const metadata = buildTrailBaseSyncMetadata(args.trail, resolution.base)
    if (metadata) {
      await args.db.trails.updateMetadata(args.repo.id, args.trail.id, metadata)
      args.trail.base = resolution.base
    }
  }

  return resolution
}

