 */
export interface TrailEvalMetricConfig {
  key: TrailEvalMetric
  agentId: string
  label: string
  description: string
  /** Card display type */
  cardType: TrailEvalCardType
  /** If true, lower scores are better (risk, drift). Only applies to score cards. */
  inverse: boolean
}

export const TRAIL_EVAL_METRIC_CONFIGS: TrailEvalMetricConfig[] = [
  {
    key: "confidence",
    agentId: "trail-confidence",
    label: "Confidence",
    description: "How sure can we be that these changes are correct and well-tested?",
    cardType: "score",
    inverse: false,
  },
  {
    key: "risk",
    agentId: "trail-risk",
    label: "Risk",
