    inverse: true,
  },
]

/**
 * Maps each trail metric to its corresponding agent ID.
 * Agent IDs follow the pattern "trail-{metric}" for trail-specific evals.
 */
export const TRAIL_METRIC_AGENT_IDS: Record<TrailEvalMetric, string> = Object.fromEntries(
  TRAIL_EVAL_METRIC_CONFIGS.map((c) => [c.key, c.agentId]),
) as Record<TrailEvalMetric, string>

