  "confidence",
  "risk",
  "drift",
  "security",
  "review_focus",
] as const satisfies readonly TrailEvalMetric[]

const V2_TRAIL_EVAL_METRICS_SET = new Set<TrailEvalMetric>(V2_TRAIL_EVAL_METRICS)

export function isV2TrailEvalMetric(metric: TrailEvalMetric | string): boolean {
  return V2_TRAIL_EVAL_METRICS_SET.has(metric as TrailEvalMetric)
}

/** Runner IDs for metrics in {@link V2_TRAIL_EVAL_METRICS} (e.g. push-router, eval reset). */
export const V2_TRAIL_EVAL_RUNNER_IDS: readonly string[] = V2_TRAIL_EVAL_METRICS.map(
  (metric) => TRAIL_METRIC_AGENT_IDS[metric],
)

const V2_TRAIL_EVAL_RUNNER_IDS_SET = new Set<string>(V2_TRAIL_EVAL_RUNNER_IDS)

export function isV2TrailEvalRunnerId(runnerId: string): boolean {
  return V2_TRAIL_EVAL_RUNNER_IDS_SET.has(runnerId)
}

/**
 * The trail-summary runner is no longer a displayed eval metric — it populates
 * the trail body when empty — but it is still launched on push through the v2
 * trail_prompt path. Treat it as migrated alongside the eval runners.
 */
export const TRAIL_BODY_RUNNER_ID = "trail-summary"

/**
 * Runner IDs the v2 push path owns, so the legacy v1 push path skips them to
 * avoid a double-run. The eval runners plus the body runner.
 */
const V2_MIGRATED_PUSH_RUNNER_IDS_SET = new Set<string>([
  ...V2_TRAIL_EVAL_RUNNER_IDS,
  TRAIL_BODY_RUNNER_ID,
])

export function isV2MigratedPushRunnerId(runnerId: string): boolean {
  return V2_MIGRATED_PUSH_RUNNER_IDS_SET.has(runnerId)
}

