export function getTrailMonitorTrend(monitor: TrailMonitorResult): TrailMonitorTrend | null {
  const delta = monitor.trend_delta
  if (typeof delta !== "number" || !Number.isFinite(delta) || delta === 0) return null

  return {
    direction: delta > 0 ? "up" : "down",
    delta,
    label: formatTrailMonitorTrendDelta(delta, monitor),
  }
}

