    repoFullName: args.repoFullName,
    repo: { default_branch: args.repoDefaultBranch },
    trail: args.trail,
    accessToken: args.token,
    fetchPullRequestState: getPullRequestState,
  })

  const shouldSyncBase =
    !args.syncBaseWhenResolvedBaseIs || resolution.base === args.syncBaseWhenResolvedBaseIs
  if (resolution.source === "pull_request" && shouldSyncBase) {
    const metadata = buildTrailBaseSyncMetadata(args.trail, resolution.base)
    if (metadata) {
