  }

  return resolution.base
}

function shouldCheckTrailMergeForPushedBranch(
  trail: TrailRow,
  repoDefaultBranch: string,
  pushedBranch: string,
): boolean {
  const storedBase = resolveBaseBranch(trail, { default_branch: repoDefaultBranch })
  if (storedBase === pushedBranch) return true

  // Older linked stacked trails may still store the repo default as their base
  // until the PR target is synced. Resolve those candidates, but do not fetch
  // PR state for every linked trail on every unrelated branch push.
  return Boolean(trail.gh_pr_id && storedBase === repoDefaultBranch)
}

