/**
 * Find an existing open PR for the given head → base.
 */
export async function findOpenPullRequest(
  repoFullName: string,
  head: string,
  base: string,
  accessToken: string,
): Promise<{ number: number; draft: boolean } | null> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=open`,
    { headers: githubHeaders(accessToken) },
  )
  if (!response.ok) {
    response.body?.cancel()
    return null
  }
  const prs = await response.json<{ number: number; draft: boolean }[]>()
  const pr = prs[0]
  if (!pr) return null
  return { number: pr.number, draft: pr.draft }
}

function normalizePullRequestBranchRef(
  data:
    | {
        ref?: unknown
        repo?: { id?: unknown; full_name?: unknown } | null
      }
    | null
    | undefined,
): PullRequestBranchRef {
  return {
    ref: typeof data?.ref === "string" ? data.ref : "",
    repo: {
      id: typeof data?.repo?.id === "number" ? data.repo.id : null,
      full_name: typeof data?.repo?.full_name === "string" ? data.repo.full_name : null,
    },
  }
}

/**
 * Find an existing open PR for the given head branch regardless of target base.
 * Used when a stored trail base may be stale, especially for stacked PRs.
 */
export async function findOpenPullRequestForHead(
  repoFullName: string,
  head: string,
  accessToken: string,
): Promise<({ number: number; draft: boolean } & Pick<PullRequestState, "head" | "base">) | null> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&state=open`,
    { headers: githubHeaders(accessToken) },
  )
  if (!response.ok) {
    response.body?.cancel()
    return null
  }
  const prs = await response.json<
    Array<{
      number: number
      draft: boolean
      head: { ref?: unknown; repo?: { id?: unknown; full_name?: unknown } | null }
      base: { ref?: unknown; repo?: { id?: unknown; full_name?: unknown } | null }
    }>
  >()
  const pr = prs[0]
  if (!pr) return null
  return {
    number: pr.number,
    draft: pr.draft,
    head: normalizePullRequestBranchRef(pr.head),
    base: normalizePullRequestBranchRef(pr.base),
  }
}

/**
 * Close a pull request by number. Silently ignores 404 (already closed/deleted).
 */
export async function closePullRequest(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    method: "PATCH",
    headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
    body: JSON.stringify({ state: "closed" }),
  })
  if (!response.ok && response.status !== 404 && response.status !== 422) {
    throw new Error(`Failed to close pull request #${prNumber}: ${response.status}`)
  }
  response.body?.cancel()
}

/**
 * Fetch the current body of a pull request via GET /repos/{owner}/{repo}/pulls/{number}.
 * Returns "" when the PR body is null.
 */
export async function fetchPullRequestBody(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
): Promise<string> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    headers: githubHeaders(accessToken),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to fetch pull request: ${response.status} - ${errorText}`)
  }

  const data = await response.json<{ body: string | null }>()
  return data.body ?? ""
}

/**
 * Update a pull request's body via PATCH /repos/{owner}/{repo}/pulls/{number}.
 */
export async function updatePullRequestBody(
  repoFullName: string,
  prNumber: number,
  body: string,
  accessToken: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    method: "PATCH",
    headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
    body: JSON.stringify({ body }),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to update pull request body: ${response.status} - ${errorText}`)
  }
}

