package main

import (
	"context"
	"encoding/json"
	"fmt"
	"io"
	"net/http"
	"net/url"
	"os"
	"strings"
	"time"

	cliauth "github.com/entireio/cli/cmd/entire/cli/auth"
)

type trailsResponse struct {
	Trails []trail `json:"trails"`
}

type trail struct {
	ID       string          `json:"id"`
	Number   int             `json:"number"`
	Title    string          `json:"title"`
	Branch   *string         `json:"branch"`
	Base     string          `json:"base"`
	Monitors json.RawMessage `json:"monitors"`
}

func main() {
	ctx, cancel := context.WithTimeout(context.Background(), 30*time.Second)
	defer cancel()

	token, err := cliauth.ResolveDataAPIToken(ctx, "https://entire.io")
	if err != nil {
		fail("resolve data token", err)
	}

	apiURL := "https://entire.io/api/v1/trails/gh/entirehq/entire.io?search=" + url.QueryEscape("fix trail base resolution") + "&limit=10"
	body, err := get(ctx, token, apiURL)
	if err != nil {
		fail("fetch trails", err)
	}
	var trails trailsResponse
	if err := json.Unmarshal(body, &trails); err != nil {
		fail("decode trails", err)
	}
	var selected *trail
	for i := range trails.Trails {
		if trails.Trails[i].Number == 1504 {
			selected = &trails.Trails[i]
			break
		}
	}
	if selected == nil {
		fmt.Printf("trail 1504 not found; candidates=%d\n", len(trails.Trails))
		for _, t := range trails.Trails {
			fmt.Printf("- #%d %s id=%s\n", t.Number, t.Title, t.ID)
		}
		return
	}
	fmt.Printf("trail #%d id=%s title=%q branch=%s base=%s\n", selected.Number, selected.ID, selected.Title, str(selected.Branch), selected.Base)
	printMonitors(selected.Monitors)

	commentsURL := "https://entire.io/api/v1/trails/" + url.PathEscape(selected.ID) + "/reviews/comments?stale=any&include_dismissed=true&limit=1000"
	body, err = get(ctx, token, commentsURL)
	if err != nil {
		fail("fetch comments", err)
	}
	printComments(body)
}

func get(ctx context.Context, token, apiURL string) ([]byte, error) {
	req, err := http.NewRequestWithContext(ctx, http.MethodGet, apiURL, nil)
	if err != nil {
		return nil, err
	}
	req.Header.Set("Authorization", "Bearer "+token)
	req.Header.Set("Accept", "application/json")
	resp, err := http.DefaultClient.Do(req)
	if err != nil {
		return nil, err
	}
	defer resp.Body.Close()
	body, _ := io.ReadAll(io.LimitReader(resp.Body, 2<<20))
	if resp.StatusCode < 200 || resp.StatusCode >= 300 {
		return nil, fmt.Errorf("status %d: %s", resp.StatusCode, strings.TrimSpace(string(body)))
	}
	return body, nil
}

func printMonitors(raw json.RawMessage) {
	var rows []map[string]any
	if err := json.Unmarshal(raw, &rows); err != nil || len(rows) == 0 {
		return
	}
	fmt.Println("monitors:")
	for _, row := range rows {
		fmt.Printf("- key=%v label=%v percent=%v size=%v bool=%v head=%v updated=%v rationale=%q\n",
			row["key"], row["label"], row["percent_value"], row["size_value"], row["boolean_value"], row["head_sha"], row["updated_at"], trim(fmt.Sprint(row["rationale"]), 180))
	}
}

func printComments(body []byte) {
	var root map[string]any
	if err := json.Unmarshal(body, &root); err != nil {
		fail("decode comments", err)
	}
	items := extractComments(root)
	fmt.Printf("comments=%d\n", len(items))
	for i, item := range items {
		path, line := location(item)
		fmt.Printf("%d. id=%v status=%v severity=%v stale=%v dismissed=%v path=%s line=%s body=%q\n",
			i+1, item["id"], item["status"], item["severity"], item["stale_outcome"], item["dismissed_at"], path, line, trim(fmt.Sprint(firstNonNil(item["body"], item["summary"], item["title"])), 220))
	}
}

func extractComments(root map[string]any) []map[string]any {
	if rows, ok := root["comments"].([]any); ok {
		return mapRows(rows)
	}
	if rows, ok := root["results"].([]any); ok {
		out := make([]map[string]any, 0, len(rows))
		for _, row := range rows {
			obj, ok := row.(map[string]any)
			if !ok {
				continue
			}
			if c, ok := obj["comment"].(map[string]any); ok {
				out = append(out, c)
			}
		}
		return out
	}
	return nil
}

func mapRows(rows []any) []map[string]any {
	out := make([]map[string]any, 0, len(rows))
	for _, row := range rows {
		if obj, ok := row.(map[string]any); ok {
			out = append(out, obj)
		}
	}
	return out
}

func location(item map[string]any) (string, string) {
	if loc, ok := item["location"].(map[string]any); ok {
		return fmt.Sprint(loc["path"]), fmt.Sprint(firstNonNil(loc["line"], loc["start_line"], loc["end_line"]))
	}
	return fmt.Sprint(item["path"]), fmt.Sprint(firstNonNil(item["line"], item["original_line"]))
}

func firstNonNil(values ...any) any {
	for _, value := range values {
		if value != nil {
			return value
		}
	}
	return ""
}

func str(s *string) string {
	if s == nil {
		return "<nil>"
	}
	return *s
}

func trim(s string, max int) string {
	s = strings.Join(strings.Fields(s), " ")
	if len(s) <= max {
		return s
	}
	return s[:max] + "..."
}

func fail(action string, err error) {
	fmt.Fprintf(os.Stderr, "%s: %v\n", action, err)
	os.Exit(1)
}

