export interface CheckRunDetail {
  /** GitHub numeric id — unique across both legacy statuses and check runs
   *  for a given commit. Use as identifier instead of name, which can collide
   *  across matrix workflow legs. */
  id: number
  name: string
  status: string
  conclusion: string | null
  html_url: string | null
  started_at: string | null
  completed_at: string | null
  app_name: string | null
}

export interface FixCiAutomationState {
  state: "running" | "completed"
  outcome?: "succeeded" | "failed" | "canceled"
  run_id: string
  started_at: string
  started_at_sha: string | null
  pushed_head_sha?: string | null
}

// "Is this check failing in a way the agent can attempt to fix?"
// Distinct from the implicit failure check used for combined-state computation
// below: that one excludes `action_required` because workflow approvals
// shouldn't read as a red display state, but for fix-CI we include it because
// the agent can sometimes resolve the underlying issue.
export function isCheckFixableByAgent(check: CheckRunDetail): boolean {
  if (check.status !== "completed" || check.conclusion === null) return false
  return (
    check.conclusion === "failure" ||
    check.conclusion === "timed_out" ||
    check.conclusion === "cancelled" ||
    check.conclusion === "action_required"
  )
}

export interface TrailCiPullRequestStatus {
  /** Tracked pull request number, if Entire has linked one to the trail. */
  number: number | null
  /** True when the UI may offer to create/link a draft PR to trigger CI. */
  can_create: boolean
}

export interface BranchCheckStatus {
  /** Combined state: "success" | "failure" | "pending" | "none" */
  state: "success" | "failure" | "pending" | "none"
  /** Total number of checks/statuses */
  total_count: number
  /** Individual check details */
  checks: CheckRunDetail[]
  /** Set when GitHub API returns 403 — indicates missing App permissions */
  permission_error?: string
  /** True when branch has merge conflicts with its target. GitHub Actions
   *  will not run pull_request-triggered workflows in this state. */
  conflict?: boolean
  /** Pull request state used by the trail CI gate. Undefined on routes that
   *  only fetch raw commit checks. */
  ci_pr?: TrailCiPullRequestStatus
  /** Latest fix-CI automation run linked to this trail. Computed fresh from
   *  the DB on every request — never cached, even when the rest of the
   *  payload is served from KV. Undefined on routes that don't surface it. */
  automation?: FixCiAutomationState | null
}

/**
 * Fetch the combined CI/checks status for a given commit ref.
 * Queries both the legacy commit status API and the newer check runs API,
 * then merges results into a unified status.
 */
export async function fetchCommitCheckStatus(
  repoFullName: string,
  ref: string,
  accessToken: string,
): Promise<BranchCheckStatus> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
  }

  // Fetch both APIs in parallel
  const [statusRes, checkRunsRes] = await Promise.all([
    fetch(`${GITHUB_API}/repos/${repoFullName}/commits/${ref}/status`, { headers }),
    fetch(`${GITHUB_API}/repos/${repoFullName}/commits/${ref}/check-runs`, { headers }),
  ])

  const checks: CheckRunDetail[] = []
  const permissionErrors: string[] = []

  // Parse legacy commit statuses
  if (statusRes.ok) {
    const statusData = await statusRes.json<{
      state: string
      statuses: Array<{
        id: number
        context: string
        state: string
        target_url: string | null
      }>
    }>()
    for (const s of statusData.statuses) {
      checks.push({
        id: s.id,
        name: s.context,
        status: s.state === "pending" ? "in_progress" : "completed",
        conclusion: s.state === "success" ? "success" : s.state === "pending" ? null : "failure",
        html_url: s.target_url,
        started_at: null,
        completed_at: null,
        app_name: null,
      })
    }
  } else {
    if (statusRes.status === 403) {
      permissionErrors.push("commit statuses (requires 'Commit statuses: Read' permission)")
    }
    statusRes.body?.cancel()
  }

  // Parse check runs
  if (checkRunsRes.ok) {
    const checkRunsData = await checkRunsRes.json<{
      total_count: number
      check_runs: Array<{
        id: number
        name: string
        status: string
        conclusion: string | null
        html_url: string | null
        started_at: string | null
        completed_at: string | null
        app: { name: string; slug: string } | null
      }>
    }>()
    for (const cr of checkRunsData.check_runs) {
      checks.push({
        id: cr.id,
        name: cr.name,
        status: cr.status,
        conclusion: cr.conclusion,
        html_url: cr.html_url,
        started_at: cr.started_at,
        completed_at: cr.completed_at,
        app_name: cr.app?.name ?? null,
      })
    }
  } else {
    if (checkRunsRes.status === 403) {
      permissionErrors.push("check runs (requires 'Checks: Read' permission)")
    }
    checkRunsRes.body?.cancel()
  }

  const permissionError =
    permissionErrors.length > 0
      ? `GitHub App missing permissions to read ${permissionErrors.join(" and ")}`
      : undefined

  if (checks.length === 0) {
    return { state: "none", total_count: 0, checks: [], permission_error: permissionError }
  }

  // Determine combined state
  const hasFailure = checks.some(
    (c) =>
      c.conclusion === "failure" || c.conclusion === "timed_out" || c.conclusion === "cancelled",
  )
  const hasPending = checks.some((c) => c.status !== "completed" || c.conclusion === null)

  let state: BranchCheckStatus["state"]
  if (hasFailure) {
    state = "failure"
  } else if (hasPending) {
    state = "pending"
  } else {
    state = "success"
  }

  return { state, total_count: checks.length, checks, permission_error: permissionError }
}

