 * Mirrors mergeBranch()'s return shape. Throws PullRequestNotMergeableError on
 * 405 (not mergeable) / 409 (head changed) so callers can surface a 422.
 */
export async function mergePullRequest(
  repoFullName: string,
  prNumber: number,
  commitTitle: string,
  accessToken: string,
  method: "merge" | "squash" | "rebase" = "merge",
  expectedHeadSha?: string | null,
): Promise<{ sha: string }> {
  const [owner, repo] = repoFullName.split("/")
  const body: { commit_title: string; merge_method: "merge" | "squash" | "rebase"; sha?: string } =
    {
      commit_title: commitTitle,
      merge_method: method,
      ...(expectedHeadSha && { sha: expectedHeadSha }),
    }
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}/merge`,
    {
      method: "PUT",
      headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
      body: JSON.stringify(body),
    },
  )

  if (response.status === 405 || response.status === 409) {
    const text = await response.text()
    throw new PullRequestNotMergeableError(
      `Pull request #${prNumber} is not mergeable: ${response.status} - ${text}`,
      response.status,
    )
  }

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Failed to merge pull request #${prNumber}: ${response.status} - ${text}`)
  }

  const data = await response.json<{ sha: string; merged: boolean }>()
  return { sha: data.sha }
}

