  3: "grid-cols-2 @[34rem]:grid-cols-3",
  4: "grid-cols-2 @[34rem]:grid-cols-4",
}

export function getTrailMonitorColumnCount(count: number) {
  if (count <= 1) return 1
  const rows = Math.ceil(count / 4)
  const columns = Math.ceil(count / rows)
  return Math.min(4, Math.max(2, columns))
}

function compareTrailMonitors(a: TrailMonitorResult, b: TrailMonitorResult) {
  const rankDelta = getTrailMonitorRank(a.key) - getTrailMonitorRank(b.key)
  if (rankDelta !== 0) return rankDelta
  return a.label.localeCompare(b.label)
}

function getTrailMonitorRank(key: string) {
  const rank: Record<string, number> = { confidence: 0, risk: 1, drift: 2, security: 3 }
  return rank[key] ?? 100
