import { request } from "@/lib/api"

import type { FileStats, SessionInfo } from "../checkpoints/api"

function trailRepoApiPath(org: string, repo: string): string {
  return `/api/v1/trails/gh/${encodeURIComponent(org)}/${encodeURIComponent(repo)}`
}

/**
 * Slim checkpoint shape returned by the trails detail endpoint. The full
 * CheckpointInfo (with patches, prompts, token usage, attribution) is only
 * used on the commit-detail page; the trails detail UI just renders a commit
 * list, so the server projects to this lighter shape.
 */
export interface TrailCheckpointSummary {
  /** Null when the branch push webhook hasn't arrived yet (matches backend). */
  commitSha: string | null
  commitMessage: string | null
  commitSubject: string | null
  commitBody: string | null
  commitAuthor: string | null
  commitAuthorUsername: string | null
  commitDate: string | null
  additions: number | null
  deletions: number | null
  filesChanged: number | null
  checkpointId: string
  sessionCount: number
  agents: string[]
}

export type TrailStatus = "draft" | "open" | "merged" | "closed"

/** Sub-state of an `open` trail, derived from branch activity. `null` for non-open trails. */
export type TrailPhase = "planning" | "building"

export type TrailPriority = "urgent" | "high" | "medium" | "low" | "none"

export type TrailType = "bug" | "feature" | "task"

export interface TrailAuthor {
  id: string
  login: string | null
}

export type TrailMonitorValueType = "percent" | "size" | "boolean"
