export type TrailMonitorPolarity = "higher_is_better" | "lower_is_better" | "neutral"

export interface TrailMonitorHistoryItem {
  percent_value: number | null
  size_value: TrailMonitorSizeValue | null
  boolean_value: boolean | null
  rationale: string | null
  evaluating?: boolean
  run_id: string
  head_sha: string | null
  updated_at: string
}

export interface TrailMonitorResult {
  key: string
  label: string
  value_type: TrailMonitorValueType
  percent_value: number | null
  size_value: TrailMonitorSizeValue | null
  boolean_value: boolean | null
  rationale: string | null
  polarity: TrailMonitorPolarity | null
  trend_delta?: number | null
  evaluating?: boolean
  history?: TrailMonitorHistoryItem[]
  run_id: string
  head_sha: string | null
  updated_at: string
}

export interface EditorDocumentSnapshot {
  id: string
  document_key: string
  schema_version: number
  content_json: unknown
  text_snapshot: string | null
  updated_at: string
}

export interface Trail {
