  number: number
  branch: string | null
  base: string
  title: string
  body_document?: EditorDocumentSnapshot | null
  monitors?: TrailMonitorResult[]
  status: TrailStatus
  /** Phase of an `open` trail (`planning` / `building`); `null` otherwise. See `getTrailDisplayStatus`. */
  phase: TrailPhase | null
  type: TrailType
