  settings: {
    trails_enabled: boolean
  }
}

export async function createTrail(
  org: string,
  repo: string,
  data: CreateTrailRequest,
): Promise<CreateTrailResponse> {
  return request<CreateTrailResponse>(trailRepoApiPath(org, repo), {
    method: "POST",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(data),
  })
}

export async function updateTrailSettings(
  repoId: string,
  settings: { trails_enabled: boolean },
): Promise<TrailSettingsResponse> {
  return request<TrailSettingsResponse>(`/api/v1/repos/${repoId}/trail-settings`, {
    method: "PATCH",
    headers: {
      "Content-Type": "application/json",
    },
    body: JSON.stringify(settings),
  })
}

