async function updateMetadata(
  db: Kysely<DB>,
  repoId: string,
  id: string,
  data: RepoTrailUpdate,
  options: TrailMetadataUpdateOptions = {},
): Promise<void> {
  assertValidUuid(repoId, "repoId")
  assertValidUuid(id, "id")

  if (Object.keys(data).length === 0) return

  await db.transaction().execute(async (tx) => {
    const updateData: Record<string, unknown> = {}
    const shouldBuildLifecycleEvents =
      options.lifecycle !== undefined && (data.status !== undefined || data.assignees !== undefined)
    const shouldLoadExisting =
      data.branch !== undefined ||
      data.base !== undefined ||
      data.status !== undefined ||
      options.expected !== undefined ||
      shouldBuildLifecycleEvents
    const existing = shouldLoadExisting ? await getTrailForUpdate(tx, repoId, id) : null
    if (shouldLoadExisting && !existing) throw new Error(`trail ${id} not found`)
    if (existing && options.expected && !trailMetadataExpectedMatches(existing, options.expected)) {
      return
    }

    if (data.branch !== undefined) {
      updateData.branch = data.branch
      if (data.branch !== null) {
        updateData.original_branch = data.branch
      } else if (existing?.branch) {
        updateData.original_branch = existing.branch
      }
    }
    if (data.base !== undefined) updateData.base = data.base
    if (data.title !== undefined) updateData.title = data.title
    if (data.body_editor_document_id !== undefined) {
      updateData.body_editor_document_id = data.body_editor_document_id
    }
    if (data.status !== undefined) {
      updateData.status = data.status
      if (data.status !== "open") updateData.has_code_changes = 0
    }
    if (data.assignees !== undefined) updateData.assignees = JSON.stringify(data.assignees)
    if (data.priority !== undefined) updateData.priority = data.priority
    if (data.type !== undefined) updateData.type = data.type
    if (data.reviewers !== undefined) updateData.reviewers = JSON.stringify(data.reviewers)
    if (data.requested_reviewers !== undefined) {
      updateData.requested_reviewers = JSON.stringify(data.requested_reviewers)
    }
    if (data.merge_base_sha !== undefined) updateData.merge_base_sha = data.merge_base_sha
    if (data.head_sha !== undefined) updateData.head_sha = data.head_sha
    if (data.updated_at !== undefined) updateData.updated_at = toDate(data.updated_at)
    if (data.merged_at !== undefined)
      updateData.merged_at = data.merged_at ? toDate(data.merged_at) : null
    if (data.gh_pr_id !== undefined) updateData.gh_pr_id = data.gh_pr_id

    const hasUpdates = Object.keys(updateData).length > 0
    if (hasUpdates) {
      await tx
        .updateTable("repo_trails")
