/**
 * Merge a head branch or commit SHA into a base branch using GitHub's merge API.
 * This creates a merge commit directly without requiring a pull request.
 */
export async function mergeBranch(
  repoFullName: string,
  head: string,
  base: string,
  commitMessage: string,
  accessToken: string,
): Promise<{ sha: string }> {
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  }

  const response = await fetch(`${GITHUB_API}/repos/${repoFullName}/merges`, {
    method: "POST",
    headers,
    body: JSON.stringify({
      base,
      head,
      commit_message: commitMessage,
    }),
  })

  if (response.status === 409) {
    throw new Error("Merge conflict: the branches cannot be merged automatically")
  }

  if (response.status === 204) {
    // 204 means base already contains the head (nothing to merge)
    return { sha: "" }
  }

  if (!response.ok) {
    const text = await response.text()
    throw new Error(`Failed to merge ${head} into ${base}: ${response.status} - ${text}`)
  }

  const data = await response.json<{ sha: string }>()
  return { sha: data.sha }
}

/** Thrown when GitHub rejects a PR merge (not mergeable / conflict). */
export class PullRequestNotMergeableError extends Error {
  status: number
  constructor(message: string, status: number) {
    super(message)
    this.name = "PullRequestNotMergeableError"
    this.status = status
  }
}

export interface MergeBlockReason {
  /** Stable snake_case identifier for the block cause. */
  reason: string
  /** Human-readable, user-facing explanation. */
  message: string
}

/**
 * Map a not-mergeable PR's GraphQL merge state to a user-facing reason.
 * `status` is the GitHub HTTP status from the failed merge (405 = not
 * mergeable, 409 = head changed). `state` is best-effort and may be null when
 * the follow-up query failed. reviewDecision takes priority over
 * mergeStateStatus because "blocked" lumps review-required in with other
 * protections, and review-required is the most common, most actionable cause.
 */
export function describeMergeBlock(
  state: { mergeStateStatus: string | null; reviewDecision: string | null } | null,
  status: number,
): MergeBlockReason {
  if (status === 409) {
    return {
      reason: "head_changed",
      message: "The branch changed while merging. Refresh the trail and try merging again.",
    }
  }
  if (state?.reviewDecision === "REVIEW_REQUIRED") {
    return {
      reason: "review_required",
      message: "Needs an approval on GitHub before you can merge",
    }
  }
  if (state?.reviewDecision === "CHANGES_REQUESTED") {
    return {
      reason: "changes_requested",
      message:
        "A reviewer requested changes on the pull request. Resolve them and get an approving " +
        "review on GitHub before merging.",
    }
  }
  switch (state?.mergeStateStatus) {
    case "DIRTY":
      return { reason: "conflict", message: "The branch has merge conflicts with the base branch." }
    case "BEHIND":
      return {
        reason: "behind",
        message: "The branch is out of date with the base branch. Update it and try again.",
      }
    case "BLOCKED":
      return {
        reason: "blocked",
        message:
          "GitHub branch protection is blocking this merge — a required status check, " +
          "code-owner review, or unresolved conversation is outstanding.",
      }
    case "DRAFT":
      return { reason: "draft", message: "The pull request is still a draft and cannot be merged." }
    default:
      return {
        reason: "not_mergeable",
        message: "This trail could not be merged. GitHub did not report a specific reason.",
      }
  }
}

/**
 * Mark a draft PR ready via GraphQL (REST can't update `draft`). Pass
 * `knownNodeId` to skip the state fetch — the caller must have confirmed the PR
 * is a draft, since this path runs the mutation unconditionally. Without it,
 * fetches state and no-ops if the PR is already ready.
