        ? (row.reviewers as unknown as TrailReviewer[])
        : []
      const approvalGatePassed =
        reviewers.length > 0 && reviewers.every((reviewer) => reviewer.status === "approved")

      let checksStatus: TrailMergeability["checks_status"] = "none"
      let checksPassed = true
      let checks: TrailMergeability["checks"] = []

