export async function createPullRequest(
  repoFullName: string,
  head: string,
  base: string,
  title: string,
  body: string,
  accessToken: string,
  options?: { prBody?: string; draft?: boolean; reopenClosed?: boolean },
): Promise<number> {
  const prBody = options?.prBody ?? body
  const [owner, repo] = repoFullName.split("/")
  const headers: Record<string, string> = {
    Accept: "application/vnd.github+json",
    "User-Agent": "entire-api",
    "X-GitHub-Api-Version": "2022-11-28",
    Authorization: `Bearer ${accessToken}`,
    "Content-Type": "application/json",
  }

  // Check for an existing closed PR for this head/base and reopen it unless
  // the caller needs a fresh PR authored by the current token owner.
  if (options?.reopenClosed !== false) {
    const closedListResponse = await fetchWithRetry(
      `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=closed`,
      { headers },
    )
    if (closedListResponse.ok) {
      const closedPrs =
        await closedListResponse.json<{ number: number; merged_at: string | null }[]>()
      // Only reopen PRs that were closed without merging
      const unmergedPr = closedPrs.find((pr) => pr.merged_at === null)
      if (unmergedPr) {
        const reopenResponse = await fetchWithRetry(
          `${GITHUB_API}/repos/${owner}/${repo}/pulls/${unmergedPr.number}`,
          {
            method: "PATCH",
            headers,
            body: JSON.stringify({
              state: "open",
              title,
              body: prBody,
              draft: options?.draft ?? false,
            }),
          },
        )
        if (reopenResponse.ok) {
          return unmergedPr.number
        }
        // If reopen fails (e.g. branch deleted), fall through to create a new one
      }
    }
  }

  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls`, {
    method: "POST",
    headers,
    body: JSON.stringify({ title, head, base, body: prBody, draft: options?.draft ?? false }),
  })

  if (response.ok) {
    const data = await response.json<{ number: number }>()
    return data.number
  }

  // If an open PR already exists for this head/base, return it
  if (response.status === 422) {
    const errorText = await response.text()
    if (errorText.includes("A pull request already exists")) {
      const listResponse = await fetchWithRetry(
        `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=open`,
        { headers },
      )
      if (listResponse.ok) {
        const prs = await listResponse.json<{ number: number }[]>()
        if (prs.length > 0) {
          return prs[0].number
        }
      }
    }
    throw new Error(`Failed to create pull request: 422 - ${errorText}`)
  }

  throw new Error(`Failed to create pull request: ${response.status}`)
}

/**
 * Find an existing open PR for the given head → base.
 */
export async function findOpenPullRequest(
  repoFullName: string,
  head: string,
  base: string,
  accessToken: string,
): Promise<{ number: number; draft: boolean } | null> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(
    `${GITHUB_API}/repos/${owner}/${repo}/pulls?head=${encodeURIComponent(`${owner}:${head}`)}&base=${encodeURIComponent(base)}&state=open`,
    { headers: githubHeaders(accessToken) },
  )
  if (!response.ok) {
    response.body?.cancel()
    return null
  }
  const prs = await response.json<{ number: number; draft: boolean }[]>()
  const pr = prs[0]
  if (!pr) return null
  return { number: pr.number, draft: pr.draft }
}

/**
 * Close a pull request by number. Silently ignores 404 (already closed/deleted).
 */
export async function closePullRequest(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    method: "PATCH",
    headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
    body: JSON.stringify({ state: "closed" }),
  })
  if (!response.ok && response.status !== 404 && response.status !== 422) {
    throw new Error(`Failed to close pull request #${prNumber}: ${response.status}`)
  }
  response.body?.cancel()
}

/**
 * Fetch the current body of a pull request via GET /repos/{owner}/{repo}/pulls/{number}.
 * Returns "" when the PR body is null.
 */
export async function fetchPullRequestBody(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
): Promise<string> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    headers: githubHeaders(accessToken),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to fetch pull request: ${response.status} - ${errorText}`)
  }

  const data = await response.json<{ body: string | null }>()
  return data.body ?? ""
}

/**
 * Update a pull request's body via PATCH /repos/{owner}/{repo}/pulls/{number}.
 */
export async function updatePullRequestBody(
  repoFullName: string,
  prNumber: number,
  body: string,
  accessToken: string,
): Promise<void> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    method: "PATCH",
    headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
    body: JSON.stringify({ body }),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to update pull request body: ${response.status} - ${errorText}`)
  }
}

