async function resolveAndMaybeSyncActiveTrailBase(args: {
  db: Db
  repo: Pick<Repo, "id" | "default_branch">
  repoFullName: string
  trail: TrailRow
  token: string
  sync?: boolean
}) {
  const resolution = await resolveActiveTrailBase({
    repoFullName: args.repoFullName,
    repo: { default_branch: args.repo.default_branch || "main" },
    trail: args.trail,
    accessToken: args.token,
    fetchPullRequestState: getPullRequestState,
  })

  if (args.sync && resolution.source === "pull_request" && resolution.base !== args.trail.base) {
    await args.db.trails.updateMetadata(args.repo.id, args.trail.id, { base: resolution.base })
    args.trail.base = resolution.base
  }

  return resolution
}

function trailThreadEventData(event: TrailThreadEventRow): unknown {
  if (event.payload && typeof event.payload === "object" && !Array.isArray(event.payload)) {
    return { ...event.payload, thread_id: event.thread_id }
  }
  return { payload: event.payload, thread_id: event.thread_id }
}

function isValidRouteUuid(value: string | undefined): value is string {
  return typeof value === "string" && isValidUuid(value)
}

function parseThreadMessageBody(c: TrailContext, raw: unknown): string | Response {
  if (typeof raw !== "string") return c.json({ error: "Message body is required" }, 400)
  const body = raw.trim()
  if (!body) return c.json({ error: "Message body is required" }, 400)
  if (body.length > TRAIL_THREAD_MESSAGE_BODY_MAX_LENGTH) {
    return c.json(
      { error: `Message body must be ${TRAIL_THREAD_MESSAGE_BODY_MAX_LENGTH} characters or fewer` },
      400,
    )
  }
  return body

