  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    method: "PATCH",
    headers: { ...githubHeaders(accessToken), "Content-Type": "application/json" },
    body: JSON.stringify({ body }),
  })

  if (!response.ok) {
    const errorText = await response.text()
    throw new Error(`Failed to update pull request body: ${response.status} - ${errorText}`)
  }
}

/**
 * Get the state of a pull request. Returns null if the PR doesn't exist (404).
 */
export async function getPullRequestState(
  repoFullName: string,
  prNumber: number,
  accessToken: string,
): Promise<PullRequestState | null> {
  const [owner, repo] = repoFullName.split("/")
  const response = await fetchWithRetry(`${GITHUB_API}/repos/${owner}/${repo}/pulls/${prNumber}`, {
    headers: githubHeaders(accessToken),
  })
  if (!response.ok) {
    response.body?.cancel()
    return null
  }
  const data = await response.json<{
    number: number
    node_id: string
    state: string
    draft: boolean
    title: string
    body: string | null
    mergeable: boolean | null
    mergeable_state: string
    head: { ref?: unknown; sha?: unknown; repo?: { id?: unknown; full_name?: unknown } | null }
    base: { ref?: unknown; sha?: unknown; repo?: { id?: unknown; full_name?: unknown } | null }
  }>()
  return {
    number: data.number,
    node_id: data.node_id,
    state: data.state,
    draft: data.draft,
    title: data.title,
    body: data.body ?? "",
    mergeable: data.mergeable,
    mergeable_state: data.mergeable_state,
    head: normalizePullRequestBranchRef(data.head),
    base: normalizePullRequestBranchRef(data.base),
  }
}

