async function replaceTrailBodyDocument(
  c: TrailContext,
  db: Db,
  document: EditorDocumentSnapshot,
  markdown: string,
  userId: string,
): Promise<EditorDocumentSnapshot> {
  const contentJson = markdownToEditorJson(markdown)

  if (!c.env.EDITOR_DOCUMENTS) {
    throw new Error("Editor collaboration not configured")
  }

  const headers = new Headers({
    "Content-Type": "application/json",
    "x-editor-document-id": document.id,
    "x-editor-document-key": document.document_key,
    "x-editor-user-id": userId,
  })
  const id = c.env.EDITOR_DOCUMENTS.idFromName(document.document_key)
  const response = await c.env.EDITOR_DOCUMENTS.get(id).fetch(
    new Request("https://editor-documents.internal/replace", {
      method: "PATCH",
      headers,
      body: JSON.stringify({ content_json: contentJson }),
    }),
  )

  if (!response.ok) {
    const errorText = await response.text().catch(() => "")
    throw new Error(`Failed to update trail body document: ${response.status} ${errorText}`)
  }

  const result = await response.json<{
    document: Parameters<typeof editorDocumentToSnapshot>[0]
  }>()
  return editorDocumentToSnapshot(result.document)
}

