function parseThreadMessageBody(c: TrailContext, raw: unknown): string | Response {
  if (typeof raw !== "string") return c.json({ error: "Message body is required" }, 400)
  const body = raw.trim()
  if (!body) return c.json({ error: "Message body is required" }, 400)
  if (body.length > TRAIL_THREAD_MESSAGE_BODY_MAX_LENGTH) {
    return c.json(
      { error: `Message body must be ${TRAIL_THREAD_MESSAGE_BODY_MAX_LENGTH} characters or fewer` },
      400,
    )
  }
  return body
}

function parseOptionalThreadTitle(c: TrailContext, raw: unknown): string | undefined | Response {
  if (raw === undefined) return undefined
  if (typeof raw !== "string") return c.json({ error: "Thread title must be a string" }, 400)
  const title = raw.trim()
  if (!title) return c.json({ error: "Thread title is required" }, 400)
  if (title.length > TRAIL_THREAD_TITLE_MAX_LENGTH) {
    return c.json(
      { error: `Thread title must be ${TRAIL_THREAD_TITLE_MAX_LENGTH} characters or fewer` },
      400,
    )
  }
  return title
}

function createTrailThreadEventStream(
  c: TrailContext,
  db: Db,
  repoFullName: string,
  userId: string,
  repoId: string,
  trailId: string,
  trailNumber: number,
  cursor: number,
): ReadableStream<Uint8Array> {
  return sseStream(c.req.raw, cursor, {
    readyPayload: { repo: repoFullName, trailNumber, trail_id: trailId },
    fetchEvents: (after) =>
      db.trails.listThreadEvents(trailId, {
        after,
        limit: 200,
        eventTypes: TRAIL_THREAD_CONVERSATION_EVENT_TYPES,
      }),
    eventData: trailThreadEventData,
    stillAuthorized: async () => {
      const result = await db.repos.getByFullNameWithAccess(repoFullName, userId)
      switch (result.status) {
        case "found":
          return result.repo.id === repoId && result.repo.trails_enabled
        case "no_access": {
          const publicRepo = await db.repos.getPublicByFullName(repoFullName)
          return publicRepo?.id === repoId && publicRepo.trails_enabled
        }
        case "not_found":
          return false
        default: {
          const unexpectedResult: never = result
          console.error(
            "Unexpected repo access result while streaming trail thread",
            unexpectedResult,
          )
          return false
        }
      }
    },
    shouldClose: async () => {
      const row = await db.trails.getById(repoId, trailId)
      if (row) return null
      return { event: "deleted", data: { repo: repoFullName, trailNumber } }
    },
    stillAuthorizedIntervalMs: TRAIL_CONVERSATION_STREAM_CHECK_INTERVAL_MS,
    shouldCloseIntervalMs: TRAIL_CONVERSATION_STREAM_CHECK_INTERVAL_MS,
  })
}

// trailWebUrl builds the canonical browser URL for a trail so API clients (the
// CLI, integrations) can surface a real link without reconstructing the route
// themselves — keeping them from drifting out of sync when the route changes.
// owner/repo come from the persisted repo identity (not the client-supplied
// path casing); host is the validated path param (VALID_HOSTS), so its casing
// is already canonical. Segments are URL-encoded via the shared buildTrailUrl.
// The decorative title slug is omitted; the detail page canonicalizes the URL
// to add it when visited.
function trailWebUrl(c: TrailContext, repo: Repo, number: number): string {
  return buildTrailUrl(c.env.FRONTEND_BASE_URL, c.req.param("host") ?? "", repo.full_name, number)
}

