      if (trail.status === "merged" || trail.status === "closed") {
        return c.json({ error: "Trail is not active" }, 409)
      }

      const user = await db.users.findById(userId)
      if (!user?.github_token_enc) {
        return c.json({ error: "GitHub token required" }, 401)
      }

      const { token } = await getValidGitHubTokenFromContext(c, db, user)

      const [headSha, comparison] = await Promise.all([
        resolveBranchSha(repoFullName, trail.branch, token),
        compareBranchStatus(repoFullName, trail.base, trail.branch, token),
      ])

      if (!headSha) {
        return c.json({ error: "Trail branch not found" }, 409)
      }

      if (comparison && comparison.ahead_by === 0) {
        return c.json({ error: "Trail branch has no changes to test" }, 409)
      }

      const prNumber = await ensureTrailPR(
        db,
        repoFullName,
        repoAccess.id,
        trail,
        token,
        c.env.FRONTEND_BASE_URL,
      )

      if (!prNumber) {
        return c.json({ error: "Unable to create a CI pull request for this trail" }, 409)
      }

      await c.env.ENTIRE_CACHE.delete(`trail-checks:${repoFullName}:${trail.number}`)
      return c.json({ pr_number: prNumber })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to create CI PR for trail #${trail.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to create CI pull request" }, 500)
    }
  },
)

// POST /:host/:owner/:repo/:number/merge — Merge a trail branch
trailRoutes.post(
  "/:host/:owner/:repo/:number/merge",
  describeRoute({
    tags: ["Trails"],
    summary: "Merge a trail branch",
    responses: {
      200: {
        description: "Trail merged",
        content: {
          "application/json": {
            schema: resolver(z.object({ ok: z.boolean(), merge_commit_sha: z.string() })),
          },
        },
      },
      422: {
        description: "Merge gate failed",
        content: {
          "application/json": {
            schema: resolver(z.object({ error: z.string(), reason: z.string().optional() })),
          },
        },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveTrailWithGitHubContext(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, trail: row, githubToken: token } = ctx

    // Set when we publish a draft backing PR during this merge — lets the catch
    // explain a likely "checks just started" failure (see below).
    let publishedDraft = false

    try {
      if (!row.branch) {
        return c.json({ error: "Trail has no linked branch" }, 422)
      }

      if (row.status !== "open") {
        return c.json({ error: "Trail must be open before it can be merged" }, 422)
      }

      const reviewers = Array.isArray(row.reviewers)
        ? (row.reviewers as unknown as TrailReviewer[])
        : []
      const allApproved =
        reviewers.length > 0 && reviewers.every((reviewer) => reviewer.status === "approved")
      if (!allApproved) {
        return c.json({ error: "Approvals required", reviewers }, 422)
      }

      const headSha = await resolveBranchSha(repoFullName, row.branch, token)
      if (headSha) {
        const checkStatus = await fetchCommitCheckStatus(repoFullName, headSha, token)
        if (checkStatus.state === "failure") {
          return c.json(
            {
              error: "CI checks have not passed",
              checks_status: checkStatus.state,
              checks: checkStatus.checks,
            },
            422,
          )
        }
        if (checkStatus.state === "pending") {
          return c.json(
            {
              error: "CI checks are still running",
              checks_status: checkStatus.state,
              checks: checkStatus.checks,
            },
            422,
          )
        }
      }

      const baseResolution = await resolveAndMaybeSyncActiveTrailBase({
        db,
        repo: repoAccess,
        repoFullName,
        trail: row,
        token,
      })
      const base = baseResolution.base
      const comparison = await compareBranchStatus(repoFullName, base, row.branch, token)
      if (!comparison) {
        return c.json(
          {
            error: "Could not verify whether this branch is up to date",
            comparison_status: "unknown",
          },
          422,
        )
      }
      if (comparison.behind_by > 0) {
        return c.json(
          {
            error: "Branch is out of date with the base branch",
            behind_by: comparison.behind_by,
            comparison_status: "available",
          },
          422,
        )
      }

      const mergeBaseSha = headSha
        ? await getMergeBaseSha(repoFullName, base, headSha, token)
        : null

      // Merge through the backing PR when one exists (satisfies branch
      // protection); fall back to the direct /merges API otherwise.
      const commitTitle = `Merge trail: ${row.title}`
      let result: { sha: string }
      // Drop the tracked PR link unless we merge through a still-open PR below.
      // Folded into the post-merge update so a failed merge never loses it.
      let clearStalePr = Boolean(row.gh_pr_id)
      const prState = baseResolution.source === "pull_request" ? baseResolution.prState : null
      if (prState) {
        clearStalePr = false
        if (prState.draft) {
          await markPullRequestReady(repoFullName, row.gh_pr_id!, token, prState.node_id)
          publishedDraft = true
        }
        const mergeMethod = pickMergeMethod(await getAllowedMergeMethods(repoFullName, token))
        result = await mergePullRequest(
          repoFullName,
          row.gh_pr_id!,
          commitTitle,
          token,
          mergeMethod,
        )
      } else {
        result = await mergeBranch(repoFullName, row.branch, base, commitTitle, token)
      }

      const now = new Date().toISOString()
      await db.trails.updateMetadata(repoAccess.id, row.id, {
        status: "merged",
        merged_at: now,
        updated_at: now,
        ...(clearStalePr && { gh_pr_id: null }),
        ...(mergeBaseSha && { merge_base_sha: mergeBaseSha }),
        ...(headSha && { head_sha: headSha }),
      })

      try {
        const deleteResult = await deleteBranch(repoFullName, row.branch, token)
        if (deleteResult.reason === "blocked") {
          console.warn(
            `Skipped deleting branch ${row.branch} after merge: ${deleteResult.message ?? "GitHub refused to delete the branch"}`,
          )
        }
      } catch (err) {
        console.error(`Failed to delete branch ${row.branch} after merge:`, err)
      }

      return c.json({ ok: true, merge_commit_sha: result.sha })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      if (err instanceof PullRequestNotMergeableError) {
        // Publishing a draft can kick off pull_request-only required checks that
        // weren't on the branch yet; the merge then fails until they pass. The
        // trail stays open (we only persist on success), so a retry succeeds.
        if (publishedDraft) {
          return c.json(
            { error: "Required checks are now running — try merging again once they pass" },
            422,
          )
        }
        // Surface GitHub's actual block reason instead of an opaque message, and
        // record it so the failure is observable (the 422 path is otherwise silent).
        recordSpanError(err)
        // A 409 (head changed) is diagnosed from status alone, so only fetch the
        // merge state when it can actually change the reason.
        const mergeState =
          err.status !== 409 && row.gh_pr_id
            ? await fetchPullRequestMergeState(repoFullName, row.gh_pr_id, token)
            : null
        const { reason, message } = describeMergeBlock(mergeState, err.status)
        return c.json({ error: message, reason }, 422)
      }
      console.error(`Failed to merge trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to merge trail" }, 500)
    }
  },
)

// POST /:host/:owner/:repo/:number/update-branch — Update a trail branch with its base
trailRoutes.post(
  "/:host/:owner/:repo/:number/update-branch",
  describeRoute({
    tags: ["Trails"],
    summary: "Update a trail branch with the latest base branch changes",
    responses: {
      200: {
        description: "Branch updated (or already up to date)",
        content: {
          "application/json": {
            schema: resolver(z.object({ ok: z.boolean(), merge_commit_sha: z.string() })),
          },
        },
      },
      409: {
        description: "Branch has merge conflicts with the base branch",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      422: {
        description: "Update gate failed",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveTrailWithGitHubContext(c)
    if (ctx instanceof Response) return ctx
    const { db, repo: repoAccess, repoFullName, trail: row, githubToken: token } = ctx

    try {
      if (!row.branch) {
        return c.json({ error: "Trail has no linked branch" }, 422)
      }

      const { base } = await resolveAndMaybeSyncActiveTrailBase({
        db,
        repo: repoAccess,
        repoFullName,
        trail: row,
        token,
      })
      const comparison = await compareBranchStatus(repoFullName, base, row.branch, token)
      if (!comparison) {
        return c.json(
          {
            error: "Could not verify whether this branch is up to date",
            comparison_status: "unknown",
          },
          422,
        )
      }
      if (comparison.behind_by === 0) {
        return c.json({ ok: true, merge_commit_sha: "" })
      }

      // GitHub's merge API merges `head` into `base`; updating the trail branch
      // means merging the trail's base branch INTO the trail branch.
      const result = await mergeBranch(
        repoFullName,
        base,
        row.branch,
        `Merge branch '${base}' into ${row.branch}`,
        token,
      )

      await c.env.ENTIRE_CACHE.delete(`trail-checks:${repoFullName}:${row.number}`)

      return c.json({ ok: true, merge_commit_sha: result.sha })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      if (err instanceof Error && err.message.startsWith("Merge conflict")) {
        return c.json(
          { error: "Branch has conflicts with the base branch that must be resolved manually" },
          409,
        )
      }
      console.error(`Failed to update branch for trail ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to update branch" }, 500)
    }
  },
)

