    const { db, userId, repo: repoAccess, repoFullName, trail: row } = ctx
    const runnerId = c.req.param("runnerId") ?? ""

    try {
      const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoAccess)
      if (tokenResult.response) return tokenResult.response
      if (!tokenResult.token) {
        return c.json({ error: "GitHub token required for this operation" }, 403)
      }

      const result = await startTrailConfiguredRun({
        env: c.env,
        db,
        repo: repoAccess,
        repoFullName,
        trail: row,
        runnerId,
        githubToken: tokenResult.token,
      })

      if (runnerId === "fix_ci") {
        if (result.kind === "existing") {
          return c.json(
            {
              error: "A fix-CI run is already in progress",
              run_id: result.run.id,
            },
            409,
          )
        }
        runInBackground(c, () =>
          c.env.ENTIRE_CACHE.delete(`trail-checks:${repoFullName}:${row.number}`),
        )
      }

      return c.json({
        runId: result.run.id,
        status: result.run.status,
        existing: result.kind === "existing",
      })
    } catch (err) {
      if (err instanceof TrailConfiguredRunUnavailableError) {
        if (runnerId === "fix_ci" && err.reason === "No failing CI checks to fix") {
          return c.json({ error: err.reason }, 409)
        }
        return c.json({ error: err.reason }, 422)
      }
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to start trail run ${runnerId} for ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to start trail run" }, 500)
    }
  },
)

// GET /:host/:owner/:repo/:number/runs/:runnerId — Fetch latest Trail runner result
trailRoutes.get(
  "/:host/:owner/:repo/:number/runs/:runnerId",
  describeRoute({
    tags: ["Trails"],
    summary: "Get the latest configured trail runner result",
    responses: {
      200: {
        description: "Trail runner result",
        content: { "application/json": { schema: resolver(trailRunResultSchema) } },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    const ctx = await resolveTrailContext(c)
    if (ctx instanceof Response) return ctx
    const { db, userId, repo: repoAccess, repoFullName, trail: row } = ctx
    const runnerId = c.req.param("runnerId") ?? ""

    try {
      const run = await db.sandboxRuns.getLatestForTrail({
        automation: runnerId,
        trail_id: row.id,
      })

      if (!run) {
        return c.json({ run: null, result: null })
      }

      const responseRun = {
        id: run.id,
        status: run.status,
        created_at: run.created_at,
        updated_at: run.updated_at,
        error_message: run.error_message,
        prompt_status: run.prompt_status,
        head_sha: run.head_sha,
      }

      if (run.status !== "succeeded") {
        return c.json({ run: responseRun, result: null })
      }

      let runnerConfig: Pick<NormalizedRunnerV2Config, "output"> | null = run.output_config
        ? { output: run.output_config }
        : null
      runnerConfig ??= getTrustedTrailRunOutputConfig(runnerId)

      if (!runnerConfig) {
        const tokenResult = await getGitHubTokenForRepoRequest(c, db, userId, repoAccess)
        if (tokenResult.response) return tokenResult.response
        if (!tokenResult.token) {
          return c.json({ error: "GitHub token required for this operation" }, 403)
        }

        try {
          const rawConfig = await fetchRunnerV2Config(
            repoFullName,
            RUNNER_V2_CONFIG_REF,
            runnerId,
            tokenResult.token,
          )
          try {
            runnerConfig = rawConfig ? normalizeRunnerV2Config(rawConfig) : null
          } catch (error) {
            console.warn(`Ignoring unsupported runner config ${runnerId} for trail run read`, error)
            runnerConfig = null
          }
        } catch (error) {
          if (runnerId !== "trail-semantic-diff") throw error
          runnerConfig = null
        }
      }

      runnerConfig ??= getTrustedTrailRunOutputConfig(runnerId)
      const resultType = runnerConfig?.output?.resultType?.trim() || null
      const adapter =
        runnerConfig?.output?.adapter && runnerConfig.output.adapter !== "none"
          ? runnerConfig.output.adapter
          : null
      const automationResult = resultType
        ? await db.sandboxRuns.getAutomationResult(run.id, resultType)
        : null

      return c.json({
        run: responseRun,
        result:
          automationResult && adapter
            ? {
                type: automationResult.result_type,
                adapter,
                data: automationResult.data,
              }
            : null,
      })
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      console.error(`Failed to fetch trail run ${runnerId} for ${row.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to fetch trail run" }, 500)
    }
  },
)

// GET /:host/:owner/:repo/:number/files — Get changed files
trailRoutes.get(
  "/:host/:owner/:repo/:number/files",
  describeRoute({
    tags: ["Trails"],
    summary: "Get changed files for a trail",
    responses: {
      200: {
        description: "Changed files",
        content: {
          "application/json": {
            schema: resolver(
              z.object({
                files: z.array(z.any()),
                additions: z.number(),
                deletions: z.number(),
              }),
            ),
          },
        },
      },
      404: {
        description: "Trail not found",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      409: {
        description: "Repository has no GitHub App installation",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
      503: {
        description: "GitHub App token temporarily unavailable",
        content: { "application/json": { schema: resolver(errorSchema) } },
      },
    },
  }),
  async (c) => {
    // Use the installation token: reading a diff doesn't act as the user, so a
    // stale/expired viewer token shouldn't break "code changes".
    const ctx = await resolveTrailWithInstallationToken(c)
    if (ctx instanceof Response) return ctx
    const { repoFullName, trail: row, githubToken: token } = ctx

    const historyBranch = row.branch ?? row.original_branch
    const snapshotBase = row.merge_base_sha
    const snapshotHead = row.head_sha
    const hasSnapshotRefs =
      (row.status === "merged" || row.status === "closed") && snapshotBase && snapshotHead

    if (!historyBranch && !hasSnapshotRefs) {
      return c.json({ files: [], additions: 0, deletions: 0 })
    }

    try {
      let result
      if (hasSnapshotRefs) {
        result = await compareBranches(repoFullName, snapshotBase, snapshotHead, token)
      } else if (historyBranch) {
        result = await compareBranches(repoFullName, row.base, historyBranch, token)
        if (result.files.length === 0 && (row.status === "merged" || row.status === "closed")) {
          result = await fetchPullRequestFiles(repoFullName, row.base, historyBranch, token)
        }
      } else {
        result = { files: [], additions: 0, deletions: 0 }
      }

      return c.json(result)
    } catch (err) {
      if (isGitHubAuthError(err)) {
        return c.json({ error: "GitHub token expired" }, 401)
      }
      if (err instanceof GitHubRateLimitError) {
        return c.json({ error: "GitHub API rate limit exceeded" }, 429)
      }
      console.error(`Failed to fetch trail files ${ctx.trail.number}:`, err)
      recordSpanError(err)
      return c.json({ error: "Failed to fetch trail files" }, 500)
    }
  },
)

