function mergeLogins(existing: string[], additions: string[]): string[] {
  const merged: string[] = []
  const seen = new Set<string>()

  for (const login of [...existing, ...additions]) {
    const trimmed = login.trim()
    if (!trimmed) continue

    const key = trimmed.toLowerCase()
    if (seen.has(key)) continue

    seen.add(key)
    merged.push(trimmed)
  }

  return merged
}

function request(
  app: ReturnType<typeof createApp>,
  path: string,
  init?: RequestInit,
  envOverrides?: Partial<Env>,
) {
  return app.request(path, init, makeMockEnv(envOverrides))
}

