/**
 * Identify new + stale checkpoint IDs, fetch their session metadata, and upsert.
 */
async function fetchAndUpsertCheckpointMetadata(
  db: Db,
  repoId: string,
  checkpointIds: string[],
  checkpointRepoFullName: string,
  token: string,
  checkpointSourceRef: string,
  storageVersion: number,
  logContext: Record<string, unknown> = {},
): Promise<{ newCount: number; newSessionIds: string[] }> {
  const existingCheckpoints = await db.checkpoints.getIdsWithCommits(repoId, checkpointIds)
  const newCheckpointIds = checkpointIds.filter((id) => !existingCheckpoints.has(id))

  // Re-fetch metadata for existing checkpoints that have incomplete session data
  // (e.g. prior token access failure on external checkpoint repos).
  const existingIds = checkpointIds.filter((id) => existingCheckpoints.has(id))
  const staleIds =
    existingIds.length > 0
      ? await db.checkpoints.getStaleCheckpointIds(repoId, existingIds)
      : new Set<string>()

  const idsToFetch = [...newCheckpointIds, ...staleIds]

  if (idsToFetch.length === 0) {
    return { newCount: newCheckpointIds.length, newSessionIds: [] }
  }

  if (staleIds.size > 0) {
    log("stale_checkpoint_re_fetch", { repoId, staleCount: staleIds.size, ...logContext })
  }

  const sessionDataResult = await fetchSessionDataBatch(
    checkpointRepoFullName,
    idsToFetch,
    token,
    checkpointSourceRef,
  )

  if (sessionDataResult.failedItems.length > 0) {
    log("session_data_partial_failure", {
      repoId,
      failed: sessionDataResult.failedItems.length,
      failedIds: sessionDataResult.failedItems,
      errors: sessionDataResult.errors,
      ...logContext,
    })
  }

  // Only upsert data for checkpoints that were successfully fetched — writing
  // back null-filled data for failed IDs would keep them stale and cause them
  // to be re-fetched on every subsequent sync.
  const failedSet = new Set(sessionDataResult.failedItems)
  const successfulIds = idsToFetch.filter((id) => !failedSet.has(id))

  if (successfulIds.length > 0) {
    const checkpointData = buildCheckpointDataFromSessionBatch(
      successfulIds,
      sessionDataResult,
      storageVersion,
    )
    await db.checkpoints.upsertSyncCheckpointBatch(repoId, checkpointData)
  }

  return {
    newCount: newCheckpointIds.length,
    newSessionIds: collectSessionIdsFromBatch(sessionDataResult),
  }
}

export async function processCheckpointPayload(
  db: Db,
  repoId: string,
  token: string,
  branch: string,
  commits: CheckpointPayloadCommit[],
  options: {
    skipAppInstallationCheck?: boolean
    dispatchAnalysis?: AnalysisDispatcher
    dispatchSessionNames?: SessionNameDispatcher
  } = {},
): Promise<{
  status: "ok" | "skipped" | "error"
  reason?: string
  checkpointsDiscovered?: number
  discoveredCheckpointIds?: string[]
}> {
  const repoData = await db.repos.getById(repoId)
  if (!repoData) return { status: "skipped", reason: "repo_not_found" }

  const repo = {
    ...repoData,
    default_branch: repoData.default_branch ?? "main",
    app_has_access: repoData.app_has_access ?? false,
  }

  if (!repo.app_has_access && !options.skipAppInstallationCheck) {
    return { status: "skipped", reason: "no_app_access" }
  }

  const discovered = commits.flatMap((commit) =>
    extractCheckpointIds(commit.message).map((checkpointId) => ({ checkpointId, commit })),
  )
  if (discovered.length === 0) {
    return { status: "ok", checkpointsDiscovered: 0, discoveredCheckpointIds: [] }
  }

  const settings = await readEntireSettingsSafe(repo.full_name, repo.default_branch, token, (err) =>
    log("settings_read_error", { repoId, error: errorString(err) }),
  )

  // Reconcile against the persisted checkpoint repo. Owner-mismatched remotes
  // fall back to the repo itself; only write when settings was successfully
  // read (or on first sync) so transient fetch errors don't flap a good value.
  try {
    const { repo: resolved, rejectedRemote } = resolveCheckpointRepo(repo.full_name, settings)
    if (rejectedRemote) {
      log("checkpoint_remote_owner_mismatch", {
        repoId,
        fullName: repo.full_name,
        configuredCheckpointRepo: rejectedRemote,
      })
    }
    const persisted = repo.checkpoint_repo_full_name
    const shouldReconcile = persisted === null || settings !== null
    if (shouldReconcile && resolved !== persisted) {
      await db.repos.updateCheckpointRepo(repoId, resolved)
      repo.checkpoint_repo_full_name = resolved
      log("checkpoint_remote_updated", {
        repoId,
        fullName: repo.full_name,
        oldCheckpointRepo: persisted,
        newCheckpointRepo: resolved,
      })
    }
  } catch (err) {
    log("checkpoint_repo_resolve_error", { repoId, error: errorString(err) })
  }

  const checkpointRepoFullName = getCheckpointRepoName(repo)
  const { storageVersion: checkpointStorageVersion, sourceRef: checkpointSourceRef } =
    resolveCheckpointSyncLocation()
  const checkpointIds = [...new Set(discovered.map((item) => item.checkpointId))]
  const { newSessionIds } = await fetchAndUpsertCheckpointMetadata(
    db,
    repoId,
    checkpointIds,
    checkpointRepoFullName,
    token,
    checkpointSourceRef,
    checkpointStorageVersion,
    { branch, source: "payload" },
  )

  // Write a junction row for every trailer pair regardless of whether the
  // matching repo_checkpoints row has landed yet — the producer's v1-ref push
  // can lose the race against the branch push, and the link has to exist for
  // the JOIN to work when hydration catches up. See migration
  // 20260522203135_drop_checkpoint_commits_fk for the full rationale.
  const commitLinks: CommitData[] = discovered.map(({ checkpointId, commit }) => ({
    checkpoint_id: checkpointId,
    branch,
    commit_sha: commit.sha,
  }))

  if (commitLinks.length > 0) {
    await db.checkpoints.upsertSyncCommitBatch(repoId, commitLinks)
    await db.checkpoints.recalculateCount(repoId)
  }

  if (newSessionIds.length > 0) {
    try {
      await db.sessions.materialise(repoId, newSessionIds)
    } catch (sessionErr) {
      log("sessions_materialise_failed", {
        repoId,
        count: newSessionIds.length,
        error: sessionErr instanceof Error ? sessionErr.message : String(sessionErr),
      })
    }
  }

  if (options.dispatchAnalysis) {
    try {
      await options.dispatchAnalysis(checkpointIds)
    } catch (err) {
      log("sync_dispatch_error", { repoId, error: errorString(err) })
    }
  }

  // We just wrote the commit-side rows, so name generation can now read every
  // commit message — trigger it for these checkpoints' sessions (the dispatcher
  // trusts them as commit-ready). Covers the case where the commit write lands
  // after the session-branch push.
  if (options.dispatchSessionNames) {
    try {
      await options.dispatchSessionNames(checkpointIds)
    } catch (err) {
      log("sync_session_name_dispatch_error", { repoId, error: errorString(err) })
    }
  }

  return {
    status: "ok",
    checkpointsDiscovered: checkpointIds.length,
    discoveredCheckpointIds: checkpointIds,
  }
}

