export function isRepoSyncMessage(msg: unknown): msg is RepoSyncMessage {
  return (
    typeof msg === "object" &&
    msg !== null &&
    "repoId" in msg &&
    "reason" in msg &&
    "priority" in msg &&
    "queuedAt" in msg &&
    typeof (msg as RepoSyncMessage).repoId === "string" &&
    typeof (msg as RepoSyncMessage).reason === "string" &&
    typeof (msg as RepoSyncMessage).priority === "number" &&
    typeof (msg as RepoSyncMessage).queuedAt === "string" &&
    (!("task" in msg) ||
      (typeof (msg as RepoSyncMessage).task === "string" &&
        ACCEPTED_REPO_SYNC_TASKS.includes(
          (msg as RepoSyncMessage).task as (typeof ACCEPTED_REPO_SYNC_TASKS)[number],
        )))
  )
