type ProcessCheckpointPayloadFields = Pick<
  RepoSyncMessage,
  "checkpointPayloadCommits" | "checkpointShas"
>

function isLegacyCheckpointPayloadMessage(
  message: ProcessCheckpointPayloadFields,
): message is Pick<LegacyProcessCheckpointsPayloadMessage, "checkpointPayloadCommits"> {
  return Array.isArray(message.checkpointPayloadCommits)
}

function isCheckpointShaMessage(
  message: ProcessCheckpointPayloadFields,
): message is Pick<ProcessCheckpointsByShaMessage, "checkpointShas"> {
  return Array.isArray(message.checkpointShas)
}

async function hydrateCheckpointCommitsFromShas(
  db: Db,
  repoId: string,
  checkpointShas: string[],
): Promise<CheckpointPayloadCommit[]> {
  const rows = await db.checkpoints.getRepoCommitsByShas(repoId, checkpointShas)
  const rowsBySha = new Map(rows.map((commit) => [commit.commit_sha, commit]))
  const commits = checkpointShas
    .map((sha) => rowsBySha.get(sha))
    .filter((commit): commit is RepoCommitData => commit !== undefined)

  if (commits.length !== checkpointShas.length) {
    const missingShas = checkpointShas.filter((sha) => !rowsBySha.has(sha))
    log("checkpoint_commit_hydration_missing", {
      repoId,
      requested: checkpointShas.length,
      found: commits.length,
      missingShas: missingShas.slice(0, 20),
    })
    throw new Error(
      `Missing checkpoint commit rows for ${missingShas.length}/${checkpointShas.length} shas`,
    )
  }

  return commits.map(repoCommitToCheckpointPayloadCommit)
}

async function resolveProcessCheckpointCommits(
  db: Db,
  repoId: string,
  message: ProcessCheckpointPayloadFields,
): Promise<CheckpointPayloadCommit[] | null> {
  if (isLegacyCheckpointPayloadMessage(message)) {
    return message.checkpointPayloadCommits
  }
  if (isCheckpointShaMessage(message)) {
    return await hydrateCheckpointCommitsFromShas(db, repoId, message.checkpointShas)
  }
  return null
}

