async function getTokenForRepoTask(
  env: Env,
  db: Db,
  batchId: string,
  repoId: string,
  reason: RepoSyncMessage["reason"],
): Promise<{ token: string; installationId: number } | { result: QueueTaskResult }> {
  const installationId = await getRepoInstallationId(db, repoId)
  if (!installationId) {
    log("no_installation_for_repo", { batchId, repoId, reason })
    return { result: { status: "skipped", reason: "no_installation_for_repo" } }
  }

  if (await isRateLimited(env.ENTIRE_CACHE, installationId)) {
    log("message_skipped_rate_limited", { batchId, repoId, installationId, reason })
    return { result: { status: "skipped", reason: "rate_limited", retry: true } }
  }

  const token = await getTokenForInstallation(installationId, env)
  if (!token) {
    log("no_token_for_repo", { batchId, repoId, installationId, reason })
    return { result: { status: "skipped", reason: "no_token_for_repo" } }
  }

  return { token, installationId }
}

