  env: Env,
  db: Db,
  args: {
    repoId: string
    repoFullName: string
    branch: string
  },
): Promise<void> {
  try {
    const { extractCheckpointIds } = await import("../github")
    const cachedCommits = await db.checkpoints.getCachedBranchCommits(args.repoId, args.branch, {
      limit: PERIODIC_CHECKPOINT_LINK_REPAIR_SCAN_LIMIT,
    })
    const checkpointPayloads = cachedCommits
      .map((commit) => {
        const ids = extractCheckpointIds(commit.commit_message ?? "")
        if (ids.length === 0) return null
        return checkpointPayloadFromCachedCommit(commit, ids)
      })
      .filter((c): c is NonNullable<typeof c> => c !== null)

    const missingPayloads = await findMissingCheckpointCommitLinks(
      db,
      args.repoId,
      args.branch,
      checkpointPayloads,
    )
    const payloadsToProcess = missingPayloads.slice(0, PERIODIC_CHECKPOINT_LINK_REPAIR_BATCH_LIMIT)
    if (checkpointPayloads.length > 0 || missingPayloads.length > 0) {
      log("checkpoint_link_periodic_repair_scan", {
        repoId: args.repoId,
        branch: args.branch,
        scanned: cachedCommits.length,
        trailerCommits: checkpointPayloads.length,
        missing: missingPayloads.length,
        enqueued: payloadsToProcess.length,
      })
    }
    await enqueueCheckpointLinkRepairs(env, { ...args, payloads: payloadsToProcess })
  } catch (err) {
    log("checkpoint_link_repair_failed", {
      repoId: args.repoId,
      branch: args.branch,
      error: errorString(err),
    })
  }
