    // 260 commits in listDAG (HEAD-first) order. The lone checkpoint commit
    // sits at index 250 — well past the 200-commit count cap — so it proves
    // checkpoint commits are enriched regardless of position.
    const CHECKPOINT_INDEX = 250
    const dagCommits = Array.from({ length: 260 }, (_, i) => ({
      sha: `sha-${i}`,
      message:
        i === CHECKPOINT_INDEX ? `feat: cp\n\nEntire-Checkpoint: cp-${i}` : `chore: commit ${i}`,
      author: {
        name: "A",
        email: "a@x",
        username: null,
        githubId: null,
        date: "2026-05-08T01:00:00.000Z",
      },
      parents: [`sha-${i + 1}`],
      url: `https://github.com/owner/repo/commit/sha-${i}`,
    }))
    mockPickGitSource.mockResolvedValue({
      resolveRef: vi.fn().mockResolvedValue("sha-0"),
      listDAG: vi.fn().mockResolvedValue(dagCommits),
    })
    mockExtractCheckpointIds.mockImplementation((message: string) =>
      message.includes("Entire-Checkpoint: ") ? ["cp-x"] : [],
    )

    const db = {
      repos: {
        getById: vi.fn().mockResolvedValue({ full_name: "owner/repo", installation_id: "inst-1" }),
      },
      installations: {
        getGithubId: vi.fn().mockResolvedValue(123),
      },
      checkpoints: {
        getBranchSyncState: vi.fn().mockResolvedValue(null),
        ensureBranchSyncState: vi.fn().mockResolvedValue(undefined),
        upsertRepoCommitBatch: vi.fn().mockResolvedValue(undefined),
        upsertRepoBranchCommitBatch: vi.fn().mockResolvedValue(undefined),
        applyAuthorResolutions: vi.fn().mockResolvedValue(0),
        deleteRecentRepoBranchCommitsNotInSet: vi.fn().mockResolvedValue(0),
        updateSyncState: vi.fn().mockResolvedValue(undefined),
      },
    } as any

    const result = await reconcileBranch({ ENTIRE_CACHE: {} } as any, db, "repo-1", "main")

    expect(result.status).toBe("ok")
    expect(mockEnqueueEnrichment).toHaveBeenCalledTimes(1)
    const enrichmentCall = mockEnqueueEnrichment.mock.calls[0][1]

    // Counts are capped at the newest 200 non-checkpoint commits (sha-0..sha-199).
    expect(enrichmentCall.countShas).toHaveLength(200)
    expect(enrichmentCall.countShas[0]).toBe("sha-0")
    expect(enrichmentCall.countShas[199]).toBe("sha-199")
    expect(enrichmentCall.countShas).not.toContain(`sha-${CHECKPOINT_INDEX}`)

    // The checkpoint commit is fully enriched even though it's past the cap.
    expect(enrichmentCall.statsShas).toEqual([`sha-${CHECKPOINT_INDEX}`])
    expect(enrichmentCall.checkpointCommits).toHaveLength(1)
    expect(enrichmentCall.checkpointCommits[0]).toMatchObject({ sha: `sha-${CHECKPOINT_INDEX}` })
  })

