export async function getCommitsForBranch(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  options: {
    limit?: number
    offset?: number
    since?: string
    until?: string
  } = {},
): Promise<CommitListItem[]> {
  const { limit = 100, offset, since, until } = options
  // Use the denormalized, indexed bc.commit_date, with repo_commits as a
  // defensive fallback for any legacy/thin-writer edge whose denormalized date
  // is still NULL. The historical backfill has populated bc.commit_date and new
  // rows are filled by the upsert path, so the fallback should be cold; keeping
  // it here preserves correctness if a gap appears.
  const effectiveDateCol = sql<Date>`COALESCE(bc.commit_date, rc.commit_date)`

  let query = db
    .selectFrom("repo_branch_commits as bc")
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "bc.repo_id").onRef("rc.commit_sha", "=", "bc.commit_sha"),
    )
    .select([
      "bc.commit_sha",
      "rc.commit_message",
      "rc.commit_author_username",
      "rc.commit_date",
      "rc.additions",
      "rc.deletions",
      "rc.files_changed",
    ])
    .where("bc.repo_id", "=", repoId)
    .where("bc.branch", "=", branch)

  if (since) query = query.where((eb) => eb(effectiveDateCol, ">=", new Date(since)))
  if (until) query = query.where((eb) => eb(effectiveDateCol, "<=", new Date(until)))

  query = query.orderBy(effectiveDateCol, "desc").limit(limit)
  if (offset) query = query.offset(offset)

  const commitRows = await query.execute()
  return enrichCommitsWithCheckpoints(
    db,
    repoId,
    commitRows.map((row) => ({
      commit_sha: row.commit_sha,
      commit_message: row.commit_message,
      commit_author_username: row.commit_author_username,
      commit_date: row.commit_date,
      additions: row.additions,
      deletions: row.deletions,
      files_changed: row.files_changed,
    })),
  )
}

export async function getCachedBranchCommits(
  db: Kysely<DB>,
  repoId: string,
  branch: string,
  options: { limit?: number } = {},
): Promise<CachedBranchCommit[]> {
  const { limit = 100 } = options
  const effectiveDateCol = sql<Date>`COALESCE(bc.commit_date, rc.commit_date)`

  const rows = await db
    .selectFrom("repo_branch_commits as bc")
    .innerJoin("repo_commits as rc", (join) =>
      join.onRef("rc.repo_id", "=", "bc.repo_id").onRef("rc.commit_sha", "=", "bc.commit_sha"),
    )
    .select(["bc.commit_sha", "rc.commit_message", "rc.commit_author_username", "rc.commit_date"])
    .where("bc.repo_id", "=", repoId)
    .where("bc.branch", "=", branch)
    .orderBy(effectiveDateCol, "desc")
    .limit(limit)
    .execute()
  return rows.map((row) => ({
