 */
export async function getCommitsBySha(
  db: Kysely<DB>,
  repoId: string,
  shas: string[],
): Promise<Map<string, CommitListItem>> {
  const uniqueShas = [...new Set(shas)]
  if (uniqueShas.length === 0) return new Map()
  if (uniqueShas.length > MAX_GET_COMMITS_BY_SHA) {
    throw new RangeError(`getCommitsBySha supports at most ${MAX_GET_COMMITS_BY_SHA} SHAs per call`)
  }

  const commitRows = await db
    .selectFrom("repo_commits as rc")
    .select([
      "rc.commit_sha",
      "rc.commit_message",
      "rc.commit_author_username",
      "rc.commit_date",
      "rc.additions",
      "rc.deletions",
      "rc.files_changed",
    ])
    .where("rc.repo_id", "=", repoId)
    .where("rc.commit_sha", "in", uniqueShas)
