import type { CommitData } from "../db/sync-types"
import { extractCheckpointIds } from "../github"

export interface CheckpointLinkAuditCommit {
  commit_sha: string
  commit_message: string | null
  commit_date: string | null
}

export interface CheckpointLinkAuditEntry {
  commit_sha: string
  checkpoint_id: string
  commit_date: string | null
  subject: string | null
}

export interface CheckpointLinkAuditNoTrailerEntry {
  commit_sha: string
  commit_date: string | null
  subject: string | null
}

export interface CheckpointLinkAuditResult {
  summary: {
    commits_audited: number
    trailer_commits_total: number
    trailer_links_total: number
    linked_links_total: number
    missing_links_total: number
    no_trailer_commits_total: number
  }
  trailer_links: CheckpointLinkAuditEntry[]
  missing_links: CheckpointLinkAuditEntry[]
  linked_links?: CheckpointLinkAuditEntry[]
  no_trailer_commits?: CheckpointLinkAuditNoTrailerEntry[]
}

function checkpointCommitLinkKey(commit: Pick<CommitData, "checkpoint_id" | "commit_sha">): string {
  return `${commit.checkpoint_id}\0${commit.commit_sha}`
}

function commitSubject(message: string | null): string | null {
  const subject = message?.split(/\r?\n/, 1)[0]?.trim()
  return subject || null
}

export function buildCheckpointLinkAudit(args: {
  commits: CheckpointLinkAuditCommit[]
  existingLinks: CommitData[]
  includeLinked?: boolean
  includeNoTrailer?: boolean
}): CheckpointLinkAuditResult {
  const existing = new Set(args.existingLinks.map(checkpointCommitLinkKey))
  const trailerLinks: CheckpointLinkAuditEntry[] = []
  const missingLinks: CheckpointLinkAuditEntry[] = []
  const linkedLinks: CheckpointLinkAuditEntry[] = []
  const noTrailerCommits: CheckpointLinkAuditNoTrailerEntry[] = []
  let trailerCommitsTotal = 0

  for (const commit of args.commits) {
    const checkpointIds = extractCheckpointIds(commit.commit_message ?? "")
    if (checkpointIds.length === 0) {
      noTrailerCommits.push({
        commit_sha: commit.commit_sha,
        commit_date: commit.commit_date,
        subject: commitSubject(commit.commit_message),
      })
      continue
    }

    trailerCommitsTotal++
    for (const checkpointId of checkpointIds) {
      const entry = {
        commit_sha: commit.commit_sha,
        checkpoint_id: checkpointId,
        commit_date: commit.commit_date,
        subject: commitSubject(commit.commit_message),
      }
      trailerLinks.push(entry)

      if (
        existing.has(
          checkpointCommitLinkKey({ checkpoint_id: checkpointId, commit_sha: commit.commit_sha }),
        )
      ) {
        linkedLinks.push(entry)
      } else {
        missingLinks.push(entry)
      }
    }
  }

  return {
    summary: {
      commits_audited: args.commits.length,
      trailer_commits_total: trailerCommitsTotal,
      trailer_links_total: trailerLinks.length,
      linked_links_total: linkedLinks.length,
      missing_links_total: missingLinks.length,
      no_trailer_commits_total: noTrailerCommits.length,
    },
    trailer_links: trailerLinks,
    missing_links: missingLinks,
    ...(args.includeLinked ? { linked_links: linkedLinks } : {}),
    ...(args.includeNoTrailer ? { no_trailer_commits: noTrailerCommits } : {}),
  }
}

