/**
 * Enqueue a `reconcile_branch` task. Throttle is enforced inside the
 * consumer — we don't drop here. Callers don't need to know whether the
 * task will run.
 */
export async function enqueueReconcileBranch(env: Env, args: EnqueueReconcileArgs): Promise<void> {
  if (!env.REPO_SYNC_QUEUE) return
  const message: RepoSyncMessage = {
    repoId: args.repoId,
    reason:
      args.reason === "drift" || args.reason === "failure" || args.reason === "audit"
        ? args.reason
        : "manual",
    priority: args.reason === "manual" ? 10 : args.reason === "drift" ? 5 : 3,
    queuedAt: new Date().toISOString(),
    task: "reconcile_branch",
    branch: args.branch,
    reconcileReason: args.reason,
  }
  if (args.delaySeconds && args.delaySeconds > 0) {
    await env.REPO_SYNC_QUEUE.send(message, { delaySeconds: args.delaySeconds })
  } else {
    await env.REPO_SYNC_QUEUE.send(message)
  }
  log("enqueued", { ...args })
}

