  branchesQueued: number
  branchListFailures: number
}

export async function enqueueReconcileForRepoBranches(
  env: Env,
  db: Db,
  repos: Array<{ id: string; full_name?: string; default_branch?: string | null }>,
  options: {
    reason: ReconcileTriggerReason
    source: string
    token?: string
    defaultBranchOnly?: boolean
  },
): Promise<EnqueueReconcileForRepoBranchesResult> {
  const result: EnqueueReconcileForRepoBranchesResult = {
    reposVisited: 0,
    branchesQueued: 0,
    branchListFailures: 0,
  }
  if (!env.REPO_SYNC_QUEUE || repos.length === 0) return result

  for (const input of repos) {
    const repo = await db.repos.getById(input.id)
    const fullName = repo?.full_name ?? input.full_name
    const defaultBranch = repo?.default_branch ?? input.default_branch ?? "main"
    if (!fullName) {
      log("repo_branch_enqueue_skipped", { repoId: input.id, reason: "missing_full_name" })
      continue
    }

    result.reposVisited++

    let branches: string[]
    if (options.defaultBranchOnly) {
      branches = defaultBranch ? [defaultBranch] : []
    } else {
      let token = options.token
      let tokenFailed = false
      if (!token && repo?.installation_id) {
        try {
          const githubInstallationId = await db.installations.getGithubId(repo.installation_id)
          if (githubInstallationId) {
            token = await getInstallationToken(
              githubInstallationId,
              {
                appId: env.GITHUB_CLIENT_ID,
                privateKey: env.GITHUB_APP_PRIVATE_KEY,
              },
              env.ENTIRE_CACHE,
            )
          }
        } catch (err) {
          tokenFailed = true
          result.branchListFailures++
          log("repo_branch_token_failed", {
            repoId: input.id,
            fullName,
            fallbackBranch: defaultBranch,
            error: errorString(err),
          })
        }
      }

      if (!tokenFailed) {
        try {
          branches = await fetchRepoBranches(fullName, token)
        } catch (err) {
          result.branchListFailures++
          log("repo_branch_list_failed", {
            repoId: input.id,
            fullName,
            fallbackBranch: defaultBranch,
            error: errorString(err),
          })
          branches = defaultBranch ? [defaultBranch] : []
        }
      } else {
        branches = defaultBranch ? [defaultBranch] : []
      }
    }

    const uniqueBranches = [...new Set(branches.length > 0 ? branches : [defaultBranch])].filter(
      (branch): branch is string => Boolean(branch),
    )

    for (const branch of uniqueBranches) {
      await enqueueReconcileBranch(env, {
        repoId: input.id,
        branch,
        reason: options.reason,
        source: options.source,
      })
      result.branchesQueued++
    }
  }

  log("repo_branches_enqueued", { ...result, source: options.source, reason: options.reason })
  return result
}

