import type {
  CheckpointInfo,
  CompareCommitSummary,
  SessionInfo,
  TrailCheckpointSummary,
} from "../types"
import { parseCommitMessage } from "./commit-message"
import { LEGACY_FALLBACK_AGENT_NAME } from "./constants"
import type { CheckpointWithCommit, CommitListItem } from "./db/checkpoints"

/** Parse the sessions JSON column without synthesizing legacy fallback session metadata. */
export function parseStoredSessions(value: unknown): SessionInfo[] | null {
  if (value == null) return null
  try {
    const parsed = typeof value === "string" ? JSON.parse(value) : value
    return Array.isArray(parsed) ? (parsed as SessionInfo[]) : null
  } catch {
    return null
  }
}

/** Parse the sessions JSON column into SessionInfo[], falling back to Unknown metadata. */
export function parseSessionsFromRow(
  row: Pick<CheckpointWithCommit, "prompt" | "sessions"> & {
    steps: number | null
  },
): SessionInfo[] {
  const parsed = parseStoredSessions(row.sessions)
  if (parsed && parsed.length > 0) {
    return parsed
  }
  return [{ prompt: row.prompt, agent: LEGACY_FALLBACK_AGENT_NAME, steps: row.steps ?? 1 }]
}

/**
 * Drop sessions whose index appears in `deadIndices`. A "dead" session is one whose
 * transcript file was missing at fetch time — the detail view already filters these from
 * its transcript response, and this helper lets list/aggregate views match that shape.
 * Null/empty deadIndices is a no-op (legacy rows, or checkpoints where every session has
 * content).
 */
export function filterLiveSessions<T>(sessions: T[], deadIndices: number[] | null): T[] {
  if (!deadIndices || deadIndices.length === 0) return sessions
  const dead = new Set(deadIndices)
  return sessions.filter((_, i) => !dead.has(i))
}

/** Map a DB checkpoint row to the API CheckpointInfo shape */
export function mapCheckpointToInfo(
  row: CheckpointWithCommit,
  checkpointRepoFullName: string | null = null,
): CheckpointInfo {
  const sessions = filterLiveSessions(parseSessionsFromRow(row), row.dead_session_indices)
  const agents = [...new Set(sessions.map((s) => s.agent))]
  const { subject, body } = parseCommitMessage(row.commit_message)
  return {
    commitSha: row.commit_sha,
    commitMessage: row.commit_message,
    commitSubject: subject,
    commitBody: body,
    commitAuthor: row.commit_author,
    commitAuthorUsername: row.commit_author_username,
    commitDate: row.commit_date,
    additions: row.additions,
    deletions: row.deletions,
    filesChanged: row.files_changed,
    filesTouched: row.files_touched,
    fileStats: row.file_stats,
    checkpointId: row.checkpoint_id,
    createdAt: row.created_at ?? new Date().toISOString(),
    sessions,
    sessionCount: sessions.length,
    totalSteps: sessions.reduce((sum, s) => sum + (s.steps ?? 1), 0),
    agents,
    inputTokens: row.input_tokens,
    cacheCreationTokens: row.cache_creation_tokens,
    cacheReadTokens: row.cache_read_tokens,
    outputTokens: row.output_tokens,
    apiCallCount: row.api_call_count,
