// Null out fields a viewer mustn't see when the source repo is public but its
// checkpoints live in a separate private storage repo. Used on list/resolve
// routes where commit metadata stays visible (commits are public on GitHub) but
// the per-session prompt text — the storage owner's private content — must not
// leak. Token usage and attribution are kept; they don't reveal prompt content.
//
// `prompt_redacted: true` is set so consumers can distinguish a hidden prompt
// from a legitimately-null one (legacy rows, empty prompts). Absent on full
// responses.
export function redactCheckpointPrivateFields(info: CheckpointInfo): CheckpointInfo {
  return {
    ...info,
    sessions: info.sessions.map((s) => ({
      ...s,
      prompt: null,
      prompt_redacted: true,
      displayName: undefined,
    })),
  }
}

/** Overlay resolved effective names onto sessions by id, mutating in place. */
export function overlaySessionDisplayNames(
  checkpoints: { sessions: SessionInfo[] }[],
  resolvedById: Map<string, string>,
): void {
  if (resolvedById.size === 0) return
  for (const checkpoint of checkpoints) {
    for (const session of checkpoint.sessions) {
      const resolved = session.sessionId ? resolvedById.get(session.sessionId) : undefined
      if (resolved !== undefined) session.displayName = resolved
    }
  }
}

