import type { Env } from "../../env"
import type { CompareCommitSummary } from "../../types"
import { getBranchDeltaPage } from "../branch-delta"
import { mapCommitListItemToCompareSummary } from "../checkpoint-mapper"
import { parseCommitMessage } from "../commit-message"
import type { Db } from "../db/db-types"
import type { GitSourceCommit, GitSourceCompareBranchStatus } from "../git-source/types"

// Safety bound on the page walk against a source that never stops paging.
const MAX_COMPARE_PAGES = 50

export interface LoadCompareCommitsOptions {
  limit: number
  offset: number
  includeSessions: boolean
  redactSessionPrompts: boolean
}

export interface CompareCommitsResult {
  aheadBy: number
  behindBy: number
  commits: CompareCommitSummary[]
}

export async function loadCompareCommits(
  env: Env,
  db: Db,
  repoAccessId: string,
  repoFullName: string,
  base: string,
  head: string,
  accessToken: string,
  options: LoadCompareCommitsOptions,
): Promise<CompareCommitsResult | null> {
  const target = options.offset + options.limit
  const collected: GitSourceCommit[] = []
  const seenShas = new Set<string>()
  let status: GitSourceCompareBranchStatus | null = null
  let pageToken: string | undefined

  // Walk pages until the window is filled or the source runs out. We always
  // fetch the first page so the compare status (aheadBy/behindBy) is returned
  // even for an empty window (target === 0). A short page is normal pagination,
  // not a failure — never throw; truncation is signalled to callers via `aheadBy`.
  for (let page = 0; page < MAX_COMPARE_PAGES; page++) {
    const delta = await getBranchDeltaPage({
      env,
      repoFullName,
      base,
      head,
      accessToken,
      pageSize: target,
      pageToken,
    })
    if (!delta) return null
    status = delta.status
    for (const commit of delta.commits) {
      if (seenShas.has(commit.sha)) continue
      seenShas.add(commit.sha)
      collected.push(commit)
    }
    if (collected.length >= target) break
    if (!delta.nextPageToken || delta.commits.length === 0) break
    if (delta.nextPageToken === pageToken) break // token not advancing — stop
    pageToken = delta.nextPageToken
  }
  if (!status) return null

  const { aheadBy, behindBy } = status
  const pagedCommits = collected.slice(options.offset, options.offset + options.limit)
  const shas = pagedCommits.map((commit) => commit.sha)
  const commitsBySha = await db.checkpoints.getCommitsBySha(repoAccessId, shas)

  const commits = pagedCommits.map((gsCommit): CompareCommitSummary => {
    const enriched = commitsBySha.get(gsCommit.sha)
    if (!enriched) {
      const { subject, body } = parseCommitMessage(gsCommit.message)
      return {
        commitSha: gsCommit.sha,
        commitMessage: gsCommit.message,
        commitSubject: subject,
        commitBody: body,
        commitAuthorUsername: gsCommit.author.username,
        commitDate: gsCommit.author.date,
        additions: null,
        deletions: null,
        filesChanged: null,
        stats_pending: true,
        checkpoints: [],
      }
    }
    return mapCommitListItemToCompareSummary(enriched, {
      includeSessions: options.includeSessions,
      redactSessionPrompts: options.redactSessionPrompts,
    })
  })

  return { aheadBy, behindBy, commits }
}

