import type { Env } from "../env"
import { pickGitSource, type GitSource } from "./git-source"
import type { GitSourceCommit, GitSourceCompareBranchStatus } from "./git-source"

const MAX_BRANCH_DELTA_PAGES = 50
const BRANCH_DELTA_PAGE_SIZE = 1000

export interface BranchDeltaPage {
  status: GitSourceCompareBranchStatus
  commits: GitSourceCommit[]
  nextPageToken: string | null
}

async function getBranchDeltaPageFromSource(args: {
  gitSource: GitSource
  repoFullName: string
  base: string
  head: string
  pageSize?: number
  pageToken?: string
}): Promise<BranchDeltaPage | null> {
  // Check refs before reading the delta. For a missing base/head, go-git may
  // return null here while listCommits({ notRef }) would reject; keeping this
  // sequential preserves a typed not-found response for callers.
  const status = await args.gitSource.compareBranchStatus(args.repoFullName, args.base, args.head)
  if (!status) return null

  const delta = await listBranchDeltaPageFromSource(args)

  return {
    status,
    commits: delta.commits,
    nextPageToken: delta.nextPageToken,
  }
}

async function listBranchDeltaPageFromSource(args: {
  gitSource: GitSource
  repoFullName: string
  base: string
  head: string
  pageSize?: number
  pageToken?: string
}): Promise<{ commits: GitSourceCommit[]; nextPageToken: string | null }> {
  return args.gitSource.listCommits(args.repoFullName, {
    branch: args.head,
    notRef: args.base,
    pageSize: args.pageSize,
    pageToken: args.pageToken,
  })
}

export async function getBranchDeltaPage(args: {
  env: Env
  repoFullName: string
  base: string
  head: string
  accessToken: string
  pageSize?: number
  pageToken?: string
}): Promise<BranchDeltaPage | null> {
  const gitSource = await pickGitSource(args.env, {
    accessToken: args.accessToken,
    repoFullName: args.repoFullName,
  })

  return getBranchDeltaPageFromSource({ ...args, gitSource })
}

export async function listBranchDeltaCommits(args: {
  env: Env
  repoFullName: string
  base: string
  head: string
  accessToken: string
}): Promise<BranchDeltaPage | null> {
  const gitSource = await pickGitSource(args.env, {
    accessToken: args.accessToken,
    repoFullName: args.repoFullName,
  })

  const status = await gitSource.compareBranchStatus(args.repoFullName, args.base, args.head)
  if (!status) return null

  const commits: GitSourceCommit[] = []
  let pageToken: string | undefined

  for (let pageCount = 0; pageCount < MAX_BRANCH_DELTA_PAGES; pageCount++) {
    const page = await listBranchDeltaPageFromSource({
      gitSource,
      repoFullName: args.repoFullName,
      base: args.base,
      head: args.head,
      pageSize: BRANCH_DELTA_PAGE_SIZE,
      pageToken,
    })
    commits.push(...page.commits)

    if (!page.nextPageToken || page.commits.length === 0) {
      return { status, commits, nextPageToken: null }
    }
    if (page.nextPageToken === pageToken) {
      throw new Error(`Branch delta pagination did not advance for ${args.repoFullName}`)
    }
    pageToken = page.nextPageToken
  }

  throw new Error(
    `Branch delta pagination exceeded ${MAX_BRANCH_DELTA_PAGES} pages for ${args.repoFullName}`,
  )
}

