    groupBy: vi.fn().mockReturnThis(),
    orderBy: vi.fn().mockReturnThis(),
    limit: vi.fn().mockReturnThis(),
    execute: mockExecute,
    executeTakeFirst: mockExecuteTakeFirst,
    executeTakeFirstOrThrow: mockExecuteTakeFirstOrThrow,
  }

  Object.keys(chainMethods).forEach((key) => {
    if (
      typeof chainMethods[key as keyof typeof chainMethods] === "function" &&
      key !== "execute" &&
      key !== "executeTakeFirst" &&
      key !== "executeTakeFirstOrThrow"
    ) {
      ;(chainMethods[key as keyof typeof chainMethods] as ReturnType<typeof vi.fn>).mockReturnValue(
        chainMethods,
      )
    }
  })

  // Transaction builder: db.transaction().setIsolationLevel(level).execute(cb)
  // invokes cb with the same chainMethods (so trx.insertInto(...) etc work
  // through the same mocks). The transaction() result intentionally does NOT
  // expose .execute — calling .execute() without first calling
  // .setIsolationLevel() throws, catching any future regression that drops
  // the isolation step.
  const txExecute = vi.fn(async (cb: (trx: typeof chainMethods) => Promise<unknown>) =>
    cb(chainMethods),
  )
  const setIsolationLevel = vi.fn().mockReturnValue({ execute: txExecute })
  const transaction = vi.fn().mockReturnValue({ setIsolationLevel })

  const mockDb = {
    ...chainMethods,
    transaction,
  }

  return {
    db: mockDb as unknown as Kysely<DB>,
    execute: mockExecute,
    executeTakeFirst: mockExecuteTakeFirst,
    executeTakeFirstOrThrow: mockExecuteTakeFirstOrThrow,
    insertInto,
    updateTable,
    set,
    selectFrom: chainMethods.selectFrom as unknown as ReturnType<typeof vi.fn>,
    select: chainMethods.select as unknown as ReturnType<typeof vi.fn>,
    where: chainMethods.where as unknown as ReturnType<typeof vi.fn>,
    orderBy: chainMethods.orderBy as unknown as ReturnType<typeof vi.fn>,
    limit: chainMethods.limit as unknown as ReturnType<typeof vi.fn>,
    values: chainMethods.values as unknown as ReturnType<typeof vi.fn>,
    transaction,
    setIsolationLevel,
    txExecute,
  }
}

