const LOG_PREFIX = "[db-checkpoints]"
const BATCH_SIZE = 50
// Keep explicit SHA lookups from turning into unbounded SQL IN lists.
const MAX_GET_COMMITS_BY_SHA = 500
const MAX_DEADLOCK_RETRIES = 8
const DEADLOCK_BACKOFF_BASE_MS = 100
const DEADLOCK_BACKOFF_JITTER_MS = 50

function normalizeJsonColumnString(value: unknown): string | null {
  if (value == null) return null
  return typeof value === "string" ? value : JSON.stringify(value)
}

function errorStringProp(err: unknown, key: string): string | null {
  if (!err || typeof err !== "object") return null
  const value = (err as Record<string, unknown>)[key]
  if (typeof value === "string") return value
  if (typeof value === "number") return String(value)
  return null
}

function isRetryableDeadlockError(err: unknown): boolean {
  const code = errorStringProp(err, "code")
  if (code === "ER_LOCK_DEADLOCK" || code === "ER_LOCK_WAIT_TIMEOUT") return true
  const sqlState = errorStringProp(err, "sqlState")
  if (sqlState === "40001") return true
  const errno = Number(errorStringProp(err, "errno"))
  if (errno === 1205 || errno === 1213) return true
  const message = err instanceof Error ? err.message.toLowerCase() : String(err).toLowerCase()
  return message.includes("deadlock") || message.includes("lock wait timeout")
}

async function executeWithDeadlockRetry(
  operation: string,
  context: Record<string, unknown>,
  fn: () => Promise<void>,
): Promise<void> {
  const span = trace.getActiveSpan()
  let lastError: unknown
  for (let attempt = 0; attempt < MAX_DEADLOCK_RETRIES; attempt++) {
    try {
      await fn()
      span?.setAttribute("app.deadlock_retry.attempts", attempt + 1)
      span?.setAttribute("app.deadlock_retry.outcome", attempt === 0 ? "first_try" : "recovered")
      return
    } catch (err) {
      lastError = err
      if (!isRetryableDeadlockError(err)) throw err
      if (attempt < MAX_DEADLOCK_RETRIES - 1) {
        console.warn(`${LOG_PREFIX} ${operation}_retry`, {
          ...context,
          attempt: attempt + 1,
          error: err instanceof Error ? err.message : String(err),
        })
        // Exponential backoff with jitter so collided txns don't immediately re-collide.
        await sleep(
          2 ** attempt * DEADLOCK_BACKOFF_BASE_MS + Math.random() * DEADLOCK_BACKOFF_JITTER_MS,
        )
      }
    }
  }

  span?.setAttribute("app.deadlock_retry.attempts", MAX_DEADLOCK_RETRIES)
  span?.setAttribute("app.deadlock_retry.outcome", "exhausted")
  // Stable substring "exhausted retries" so dashboards/alerts survive future
  // tuning of MAX_DEADLOCK_RETRIES.
  throw new Error(`${operation} exhausted retries after ${MAX_DEADLOCK_RETRIES} attempts`, {
    cause: lastError,
  })
}

