/**
 * Throttle window for a (repo_id, branch) pair. Drift / failure / audit
 * all share this throttle; periodic respects it too. Bypass via the manual
 * admin endpoint when an operator explicitly wants to skip the gate.
 */
const RECONCILE_THROTTLE_MS = 60 * 1000

/**
 * Cap on how many commits to fetch on each reconcile. Plan assumes 1-2s for
 * 1000 commits; 2000 buys headroom for repos with very long active branches.
 */
const RECONCILE_DAG_MAX_COMMITS = 2000

/**
 * Cap on non-checkpoint commits handed to cheap count-enrichment per reconcile.
