/** Collect every session id mentioned in a fetched session-data batch. */
function collectSessionIdsFromBatch(sessionDataResult: BatchResult<SessionData>): string[] {
  const seen = new Set<string>()
  for (const session of sessionDataResult.data.values()) {
    if (session.sessionId) seen.add(session.sessionId)
    if (session.sessionIds) {
      for (const id of session.sessionIds) {
        if (id) seen.add(id)
      }
    }
  }
  return [...seen]
}

