/**
 * Identify new + stale checkpoint IDs, fetch their session metadata, and upsert.
 */
async function fetchAndUpsertCheckpointMetadata(
  db: Db,
  repoId: string,
  checkpointIds: string[],
  checkpointRepoFullName: string,
  token: string,
  checkpointSourceRef: string,
  storageVersion: number,
  logContext: Record<string, unknown> = {},
): Promise<{ newCount: number; newSessionIds: string[] }> {
  const existingCheckpoints = await db.checkpoints.getIdsWithCommits(repoId, checkpointIds)
  const newCheckpointIds = checkpointIds.filter((id) => !existingCheckpoints.has(id))

  // Re-fetch metadata for existing checkpoints that have incomplete session data
  // (e.g. prior token access failure on external checkpoint repos).
  const existingIds = checkpointIds.filter((id) => existingCheckpoints.has(id))
  const staleIds =
    existingIds.length > 0
      ? await db.checkpoints.getStaleCheckpointIds(repoId, existingIds)
      : new Set<string>()

  const idsToFetch = [...newCheckpointIds, ...staleIds]

  if (idsToFetch.length === 0) {
    return { newCount: newCheckpointIds.length, newSessionIds: [] }
  }

  if (staleIds.size > 0) {
    log("stale_checkpoint_re_fetch", { repoId, staleCount: staleIds.size, ...logContext })
  }

  const sessionDataResult = await fetchSessionDataBatch(
    checkpointRepoFullName,
    idsToFetch,
    token,
    checkpointSourceRef,
  )

  if (sessionDataResult.failedItems.length > 0) {
    log("session_data_partial_failure", {
      repoId,
      failed: sessionDataResult.failedItems.length,
      failedIds: sessionDataResult.failedItems,
      errors: sessionDataResult.errors,
      ...logContext,
    })
  }

  // Only upsert data for checkpoints that were successfully fetched — writing
  // back null-filled data for failed IDs would keep them stale and cause them
  // to be re-fetched on every subsequent sync.
  const failedSet = new Set(sessionDataResult.failedItems)
  const successfulIds = idsToFetch.filter((id) => !failedSet.has(id))

  if (successfulIds.length > 0) {
    const checkpointData = buildCheckpointDataFromSessionBatch(
      successfulIds,
      sessionDataResult,
      storageVersion,
    )
    await db.checkpoints.upsertSyncCheckpointBatch(repoId, checkpointData)
  }

  return {
    newCount: newCheckpointIds.length,
    newSessionIds: collectSessionIdsFromBatch(sessionDataResult),
  }
}

